export const generateTxtReport = (data: ReportData): string => {
    const { formData, results, calculationType, cultureParams, springFertilizer, nitrogenFertilizer, complexFertilizer, basicFertilizers, selectedAmendment, springFertilizerRate, lang } = data;

    const fieldArea = parseFloat(formData.fieldArea || '1') || 1;
    const cultureName = CULTURES.find(c => c.key === formData.culture)?.name[lang] || formData.culture;

    let report = `==================================================\n`;
    report += `   HarvestConsulting\n`;
    report += `   Лашин Олександр Володимирович\n`;
    report += `   lashyn.aleksandr@gmail.com\n`;
    report += `==================================================\n\n`;
    report += `   ${t('resultsTitle', lang, { cultureName: cultureName })}\n`;
    report += `==================================================\n\n`;

    report += `---------- ${t('inputData', lang)} ----------\n`;
    if (formData.fieldName) {
        report += `${t('fieldNameLabel', lang)}: ${formData.fieldName}\n`;
    }
    report += `${t('cultureLabel', lang)}: ${cultureName}\n`;
    if (formData.sowingDate) {
        report += `${t('sowingDateLabel', lang)}: ${new Date(formData.sowingDate).toLocaleDateString(lang === 'uk' ? 'uk-UA' : 'en-CA')}\n`;
    }
    report += `${t('plannedYieldLabel', lang)}: ${formData.plannedYield} t/ha\n`;
    report += `${t('fieldAreaLabel', lang)}: ${fieldArea} ha\n\n`;

    report += `${t('soilAnalysis', lang)}:\n`;
    report += `  - N: ${formData.nitrogenAnalysis} mg/kg\n`;
    report += `  - P2O5: ${formData.phosphorus} mg/kg\n`;
    report += `  - K2O: ${formData.potassium} mg/kg\n`;
    report += `  - CaO: ${formData.calcium} mg/kg\n`;
    report += `  - MgO: ${formData.magnesium} mg/kg\n`;
    report += `  - pH: ${formData.ph}\n`;
    report += `  - CEC: ${formData.cec} mg-eq/100g\n\n`;

    if (calculationType === 'basic' || calculationType === 'full') {
        report += `---------- ${t('basicApplicationSection', lang)} ----------\n\n`;

        let finalBasicNeeds = [...results.basic];

        if (complexFertilizer && complexFertilizer.enabled && parseFloat(complexFertilizer.rate) > 0) {
            const rate = parseFloat(complexFertilizer.rate);
            const identifiedName = getIdentifiedComplexName(complexFertilizer.n, complexFertilizer.p2o5, complexFertilizer.k2o, complexFertilizer.cao, complexFertilizer.mg, lang);
            const label = identifiedName ? `${identifiedName} (${t('complexFertilizer', lang)})` : t('complexFertilizer', lang);

            report += `${label}:\n`;
            report += `  - ${t('composition', lang)}: N:${complexFertilizer.n}% P2O5:${complexFertilizer.p2o5}% K2O:${complexFertilizer.k2o}% CaO:${complexFertilizer.cao}% MgO:${complexFertilizer.mg}%\n`;
            report += `  - ${t('applicationRate', lang)}: ${rate} kg/ha (${t('totalLabel', lang)}: ${(rate * fieldArea).toFixed(1)} kg)\n\n`;

            const supplied = {
                'P2O5': rate * (parseFloat(complexFertilizer.p2o5 || '0') / 100),
                'K2O': rate * (parseFloat(complexFertilizer.k2o || '0') / 100),
                'CaO': rate * (parseFloat(complexFertilizer.cao || '0') / 100),
                'MgO': rate * (parseFloat(complexFertilizer.mg || '0') / 100),
            };
            finalBasicNeeds = finalBasicNeeds.map(need => {
                const suppliedAmount = supplied[need.element as keyof typeof supplied] || 0;
                return { ...need, norm: Math.round(Math.max(0, need.norm - suppliedAmount)) };
            });
        }

        const ph = parseFloat(formData.ph);
        const needsAmendment = ph <= 6.8;
        let amendmentRateKg = 0;

        if (needsAmendment && selectedAmendment) {
             const amendmentEffects = AMENDMENT_EFFECTS[selectedAmendment as keyof typeof AMENDMENT_EFFECTS];
             const amendmentRateTons = Math.round((7 - ph) * 5);
             amendmentRateKg = amendmentRateTons * 1000;
             const caFromAmendment = amendmentEffects.calcium * amendmentRateTons;
             const mgFromAmendment = amendmentEffects.magnesium * amendmentRateTons;

             finalBasicNeeds = finalBasicNeeds.map(need => {
                 if (need.element === 'CaO') return { ...need, norm: Math.round(Math.max(0, need.norm - caFromAmendment)) };
                 if (need.element === 'MgO') return { ...need, norm: Math.round(Math.max(0, need.norm - mgFromAmendment)) };
                 return need;
             });
        }

        report += `${t('remainingNeed', lang)}:\n`;
        finalBasicNeeds.forEach(need => {
            if (need.element !== 'Меліорант' && need.norm > 0) {
                const selection = basicFertilizers[need.element];
                let fertInfo = '';
                if(selection && selection.selectedFertilizer) {
                    const percentage = parseFloat(selection.selectedFertilizer);
                    const fertName = SIMPLE_FERTILIZERS[need.element as keyof typeof SIMPLE_FERTILIZERS]?.find(f => f.value.toString() === selection.selectedFertilizer)?.label[lang] || '';
                    if (percentage > 0) {
                        const physRate = (need.norm / percentage) * 100;
                        fertInfo = ` -> ${fertName}: ${physRate.toFixed(1)} kg/ha (${t('totalLabel', lang)}: ${(physRate * fieldArea).toFixed(1)} kg)`;
                    }
                }
                report += `  - ${pad(need.element, 6)}: ${need.norm} kg a.i./ha ${fertInfo}\n`;
            }
        });
        report += '\n';

        if (needsAmendment && selectedAmendment && amendmentRateKg > 0) {
             const amendLabel = AMENDMENTS.find(a => a.value === selectedAmendment)?.label[lang] || selectedAmendment;
             report += `${t('amendmentLabel', lang)}:\n`;
             report += `  - ${amendLabel}: ${amendmentRateKg} kg/ha (${t('totalLabel', lang)}: ${(amendmentRateKg * fieldArea).toFixed(0)} kg)\n\n`;
        }
    }

    if (calculationType === 'fertigation' || calculationType === 'full') {
        report += `---------- ${t('fertigationProgramSection', lang)} ----------\n\n`;

        const findCultureKey = (cultureName: string) => {
            return Object.keys(FERTIGATION_CULTURES).find(key => 
                FERTIGATION_CULTURES[key as keyof typeof FERTIGATION_CULTURES].startsWith(cultureName)
            );
        };
        const cultureKey = findCultureKey(results.culture);

        if (cultureKey) {
            const { weeklyPlan, totals } = calculateFertigationPlan({
                initialNeeds: results.fertigation, cultureKey, cultureParams, springFertilizer, nitrogenFertilizer, manualRate: springFertilizerRate
            });

            if (springFertilizer.enabled && springFertilizerRate && springFertilizerRate > 0) {
                 const identifiedName = getIdentifiedComplexName(springFertilizer.n, springFertilizer.p, springFertilizer.k, springFertilizer.ca, springFertilizer.mg, lang);
                 const label = identifiedName ? `${identifiedName} (${t('springFertilizer', lang)})` : t('springFertilizer', lang);

                 report += `${label}:\n`;
                 report += `  - ${t('composition', lang)}: N:${springFertilizer.n}% P:${springFertilizer.p}% K:${springFertilizer.k}% Ca:${springFertilizer.ca}% Mg:${springFertilizer.mg}%\n`;
                 report += `  - ${t('applicationRate', lang)}: ${springFertilizerRate.toFixed(1)} kg/ha (${t('totalLabel', lang)}: ${(springFertilizerRate * fieldArea).toFixed(1)} kg)\n\n`;
            }

            const nFertName = nitrogenFertilizer === 'ammonium-nitrate' ? t('ammoniumNitrate', lang) : t('urea', lang);
            const headers = [t('week', lang), nFertName, t('phosphoricAcid', lang), t('potassiumSulfate', lang), t('calciumNitrate', lang), t('magnesiumSulfate', lang)];
            const pads = [20, 18, 18, 16, 16, 16];

            report += `${t('weeklyPlanHeader', lang)}\n\n`;

            let headerLine = "|";
            let separatorLine = "|";
            headers.forEach((h, i) => {
                headerLine += ` ${pad(h, pads[i])}|`;
                separatorLine += `${'-'.repeat(pads[i] + 2)}|`;
            });
            report += `${separatorLine}\n${headerLine}\n${separatorLine}\n`;

            weeklyPlan.forEach(item => {
                if(item) {
                     const weekLabel = `${item.week} ${getWeekDateRangeText(formData.sowingDate, item.week)}`;
                    const rowData = [
                        weekLabel,
                        `${item.nitrogen.toFixed(1)} (${(item.nitrogen * fieldArea).toFixed(1)})`,
                        `${item.phosphorus.toFixed(1)} (${(item.phosphorus * fieldArea).toFixed(1)})`,
                        `${item.potassium.toFixed(1)} (${(item.potassium * fieldArea).toFixed(1)})`,
                        `${item.calcium.toFixed(1)} (${(item.calcium * fieldArea).toFixed(1)})`,
                        `${item.magnesium.toFixed(1)} (${(item.magnesium * fieldArea).toFixed(1)})`,
                    ];
                    let rowLine = "|";
                    rowData.forEach((d, i) => {
                        rowLine += ` ${pad(d, pads[i])}|`;
                    });
                    report += `${rowLine}\n`;
                }
            });

            const totalLineData = [
                t('totalLabel', lang),
                 `${totals.nitrogen.toFixed(1)} (${(totals.nitrogen * fieldArea).toFixed(1)})`,
                 `${totals.phosphorus.toFixed(1)} (${(totals.phosphorus * fieldArea).toFixed(1)})`,
                 `${totals.potassium.toFixed(1)} (${(totals.potassium * fieldArea).toFixed(1)})`,
                 `${totals.calcium.toFixed(1)} (${(totals.calcium * fieldArea).toFixed(1)})`,
                 `${totals.magnesium.toFixed(1)} (${(totals.magnesium * fieldArea).toFixed(1)})`,
            ];
            let totalLineStr = "|";
            totalLineData.forEach((d, i) => {
                totalLineStr += ` ${pad(d, pads[i])}|`;
            });

            report += `${separatorLine}\n${totalLineStr}\n${separatorLine}\n\n`;
        }
    }

    report += `\n==================================================\n`;
    report += `   HarvestConsulting\n`;
    report += `==================================================\n`;

    return report;
};

const addValueToProcurement = (procurement: Record<string, number>, key: string, value: number) => {
    if (!key || isNaN(value) || value <= 0) return;
    const normalizedKey = key.trim();
    procurement[normalizedKey] = (procurement[normalizedKey] || 0) + value;
};

const generateSummarySheet = (reports: ReportData[], lang: Language) => {
    const preSeasonTotals: Record<string, number> = {};
    const monthlyTotals: Record<string, Record<string, number>> = {};

    reports.forEach(report => {
        const { formData, results, cultureParams, springFertilizer, nitrogenFertilizer, complexFertilizer, basicFertilizers, selectedAmendment, springFertilizerRate } = report;
        const fieldArea = parseFloat(formData.fieldArea) || 1;

        if (complexFertilizer && complexFertilizer.enabled && parseFloat(complexFertilizer.rate) > 0) {
             const n = Math.round(parseFloat(complexFertilizer.n || '0'));
             const p = Math.round(parseFloat(complexFertilizer.p2o5 || '0'));
             const k = Math.round(parseFloat(complexFertilizer.k2o || '0'));
             const idName = getIdentifiedComplexName(complexFertilizer.n, complexFertilizer.p2o5, complexFertilizer.k2o, complexFertilizer.cao, complexFertilizer.mg, lang);
             const name = idName ? `${idName} (N${n}-P${p}-K${k})` : `${t('complexFertilizer', lang)} N${n}-P${p}-K${k}`;
             addValueToProcurement(preSeasonTotals, name, parseFloat(complexFertilizer.rate) * fieldArea);
        }

        if (springFertilizer && springFertilizer.enabled && springFertilizerRate && springFertilizerRate > 0) {
            const n = Math.round(parseFloat(springFertilizer.n || '0'));
            const p = Math.round(parseFloat(springFertilizer.p || '0'));
            const k = Math.round(parseFloat(springFertilizer.k || '0'));
            const idName = getIdentifiedComplexName(springFertilizer.n, springFertilizer.p, springFertilizer.k, springFertilizer.ca, springFertilizer.mg, lang);
            const name = idName ? `${idName} (N${n}-P${p}-K${k})` : `${t('springFertilizer', lang)} N${n}-P${p}-K${k}`;
            addValueToProcurement(preSeasonTotals, name, springFertilizerRate * fieldArea);
        }

        if(selectedAmendment) {
            const ph = parseFloat(formData.ph);
            if (ph <= 6.8) {
                const amendRate = Math.round((7 - ph) * 5) * 1000;
                const name = AMENDMENTS.find(a => a.value === selectedAmendment)?.label[lang] || selectedAmendment;
                addValueToProcurement(preSeasonTotals, name, amendRate * fieldArea);
            }
        }

        let finalBasicNeeds = [...results.basic];
        if (complexFertilizer && complexFertilizer.enabled && parseFloat(complexFertilizer.rate) > 0) {
            const rate = parseFloat(complexFertilizer.rate);
            const supplied = {
                'P2O5': rate * (parseFloat(complexFertilizer.p2o5 || '0') / 100), 'K2O': rate * (parseFloat(complexFertilizer.k2o || '0') / 100),
                'CaO': rate * (parseFloat(complexFertilizer.cao || '0') / 100), 'MgO': rate * (parseFloat(complexFertilizer.mg || '0') / 100),
            };
            finalBasicNeeds = finalBasicNeeds.map(need => ({ ...need, norm: Math.round(Math.max(0, need.norm - (supplied[need.element as keyof typeof supplied] || 0))) }));
        }

        Object.keys(basicFertilizers).forEach(el => {
            const fertValue = basicFertilizers[el]?.selectedFertilizer;
            const fert = SIMPLE_FERTILIZERS[el as keyof typeof SIMPLE_FERTILIZERS]?.find(f => f.value.toString() === fertValue);
            const need = finalBasicNeeds.find(n => n.element === el)?.norm || 0;
            if (fert && need > 0) {
                const physRate = (need / fert.value) * 100;
                addValueToProcurement(preSeasonTotals, fert.label[lang], physRate * fieldArea);
            }
        });

        const cultureKey = Object.keys(FERTIGATION_CULTURES).find(key => FERTIGATION_CULTURES[key as keyof typeof FERTIGATION_CULTURES].startsWith(results.culture));
        if (cultureKey && formData.sowingDate) {
             const { weeklyPlan } = calculateFertigationPlan({ initialNeeds: results.fertigation, cultureKey, cultureParams, springFertilizer, nitrogenFertilizer, manualRate: springFertilizerRate });
             const fertNames = [
                nitrogenFertilizer === 'urea' ? t('urea', lang) : t('ammoniumNitrate', lang),
                t('phosphoricAcid', lang), t('potassiumSulfate', lang), t('calciumNitrate', lang), t('magnesiumSulfate', lang)
             ];

             weeklyPlan.forEach(week => {
                const sowDate = new Date(formData.sowingDate);
                const weekStartDate = new Date(sowDate);
                weekStartDate.setDate(sowDate.getDate() + (week.week - 1) * 7);
                const monthName = t(`month_${weekStartDate.getMonth()}` as TranslationKey, lang);
                const weeklyVals = [week.nitrogen, week.phosphorus, week.potassium, week.calcium, week.magnesium];

                fertNames.forEach((name, i) => {
                    if (weeklyVals[i] > 0) {
                        if (!monthlyTotals[name]) monthlyTotals[name] = {};
                        monthlyTotals[name][monthName] = (monthlyTotals[name][monthName] || 0) + (weeklyVals[i] * fieldArea);
                    }
                });
             });
        }
    });

    const preSeasonSheetData = Object.entries(preSeasonTotals).map(([name, total]) => ({
        [t('fertilizerNameHeader', lang)]: name,
        [t('totalNeededKgHeader', lang)]: parseFloat(total.toFixed(1))
    }));

    const allMonths = [...new Set(Object.values(monthlyTotals).flatMap(months => Object.keys(months)))].sort((a, b) => {
         const monthOrder = Array.from({length: 12}, (_, i) => t(`month_${i}` as TranslationKey, lang));
         return monthOrder.indexOf(a) - monthOrder.indexOf(b);
    });

    const monthlySheetData = Object.keys(monthlyTotals).sort().map(fertName => {
        const row: Record<string, any> = { [t('fertilizerNameHeader', lang)]: fertName };
        let total = 0;
        allMonths.forEach(month => {
            const val = monthlyTotals[fertName][month] || 0;
            row[month] = val > 0 ? parseFloat(val.toFixed(1)) : '';
            total += val;
        });
        row[t('totalLabel', lang)] = parseFloat(total.toFixed(1));
        return row;
    });

    let aoa: any[][] = [];
    addCorporateHeader(aoa, t('summarySheet', lang));
    const startRow = aoa.length;

    const wsSummary = XLSX.utils.aoa_to_sheet(aoa);
    XLSX.utils.sheet_add_aoa(wsSummary, [[t('preSeasonFertilizersHeader', lang)]], { origin: `A${startRow + 1}` });
    XLSX.utils.sheet_add_json(wsSummary, preSeasonSheetData, { origin: `A${startRow + 2}`, skipHeader: false });

    const nextRow = startRow + preSeasonSheetData.length + 5;
    XLSX.utils.sheet_add_aoa(wsSummary, [[t('monthlyNeedsHeader', lang)]], { origin: `A${nextRow}` });
    XLSX.utils.sheet_add_json(wsSummary, monthlySheetData, { origin: `A${nextRow + 1}`, skipHeader: false });

    wsSummary['!cols'] = [ { wch: 45 }, ...allMonths.map(() => ({ wch: 15 })), { wch: 20 } ];
    wsSummary['!merges'] = getMergesForHeader(0);
    return wsSummary;
};

const generateDetailsSheet = (reports: ReportData[], lang: Language) => {
    let aoa: any[][] = [];
    addCorporateHeader(aoa, t('detailsSheet', lang));

    reports.forEach((report, index) => {
        const { formData, results, cultureParams, springFertilizer, nitrogenFertilizer, complexFertilizer, basicFertilizers, selectedAmendment, springFertilizerRate } = report;
        const cultureName = CULTURES.find(c => c.key === formData.culture)?.name[lang] || formData.culture;
        const fieldArea = parseFloat(formData.fieldArea) || 1;

        if (index > 0) aoa.push([], ["------------------------------------------------------------------------------------------------"]); 

        aoa.push([t('reportFor', lang, { culture: formData.fieldName || cultureName })]);
        aoa.push([`${t('cultureLabel', lang)}: ${cultureName}`, `${t('fieldAreaLabel', lang)}: ${fieldArea} ha`, `${t('sowingDateLabel', lang)}: ${formData.sowingDate || '-'}`]);
        aoa.push([]);

        if (report.calculationType === 'basic' || report.calculationType === 'full') {
            aoa.push([t('basicApplicationSection', lang)]);
            aoa.push([t('fertilizerTypeHeader', lang), t('fertilizerNameCompositionHeader', lang), `${t('applicationRate', lang)} (kg/ha)`, `${t('totalLabel', lang)} (kg)`]);

            let finalNeeds = [...results.basic];
            if (complexFertilizer && complexFertilizer.enabled && parseFloat(complexFertilizer.rate) > 0) {
                const idName = getIdentifiedComplexName(complexFertilizer.n, complexFertilizer.p2o5, complexFertilizer.k2o, complexFertilizer.cao, complexFertilizer.mg, lang);
                const label = idName ? `${idName} (${t('complexFertilizer', lang)})` : t('complexFertilizer', lang);
                const comp = `N:${complexFertilizer.n} P:${complexFertilizer.p2o5} K:${complexFertilizer.k2o}`;
                const rate = parseFloat(complexFertilizer.rate);
                aoa.push([label, comp, rate, rate * fieldArea]);

                const supplied = {
                    'P2O5': rate * (parseFloat(complexFertilizer.p2o5 || '0') / 100), 'K2O': rate * (parseFloat(complexFertilizer.k2o || '0') / 100),
                    'CaO': rate * (parseFloat(complexFertilizer.cao || '0') / 100), 'MgO': rate * (parseFloat(complexFertilizer.mg || '0') / 100),
                };
                finalNeeds = finalNeeds.map(need => ({ ...need, norm: Math.round(Math.max(0, need.norm - (supplied[need.element as keyof typeof supplied] || 0))) }));
            }

            const ph = parseFloat(formData.ph);
            if (ph <= 6.8 && selectedAmendment) {
                const amendRate = Math.round((7 - ph) * 5) * 1000;
                const name = AMENDMENTS.find(a => a.value === selectedAmendment)?.label[lang] || selectedAmendment;
                aoa.push([t('amendmentLabel', lang), name, amendRate, amendRate * fieldArea]);
            }

            finalNeeds.filter(n => n.norm > 0).forEach(need => {
                const sel = basicFertilizers[need.element];
                const fert = sel ? SIMPLE_FERTILIZERS[need.element as keyof typeof SIMPLE_FERTILIZERS]?.find(f => f.value.toString() === sel.selectedFertilizer) : null;
                if (fert) {
                    const rate = (need.norm / fert.value) * 100;
                    aoa.push([`${t('fertilizerLabel', lang)} (${need.element})`, fert.label[lang], parseFloat(rate.toFixed(1)), parseFloat((rate * fieldArea).toFixed(1))]);
                } else {
                    aoa.push([`${t('fertilizerLabel', lang)} (${need.element})`, `${t('need', lang)}: ${need.norm} kg a.i.`, '-', '-']);
                }
            });
            aoa.push([]);
        }

        if (report.calculationType === 'fertigation' || report.calculationType === 'full') {
            aoa.push([t('fertigationProgramSection', lang)]);
            if (springFertilizer.enabled && springFertilizerRate && springFertilizerRate > 0) {
                const idName = getIdentifiedComplexName(springFertilizer.n, springFertilizer.p, springFertilizer.k, springFertilizer.ca, springFertilizer.mg, lang);
                const label = idName ? `${idName} (${t('springFertilizer', lang)})` : t('springFertilizer', lang);
                aoa.push([label, `N:${springFertilizer.n} P:${springFertilizer.p} K:${springFertilizer.k}`, springFertilizerRate, springFertilizerRate * fieldArea]);
            }

            const cultureKey = Object.keys(FERTIGATION_CULTURES).find(key => FERTIGATION_CULTURES[key as keyof typeof FERTIGATION_CULTURES].startsWith(results.culture));
            if (cultureKey) {
                const { weeklyPlan, totals } = calculateFertigationPlan({ initialNeeds: results.fertigation, cultureKey, cultureParams, springFertilizer, nitrogenFertilizer, manualRate: springFertilizerRate });
                const fNames = [nitrogenFertilizer === 'urea' ? t('urea', lang) : t('ammoniumNitrate', lang), t('phosphoricAcid', lang), t('potassiumSulfate', lang), t('calciumNitrate', lang), t('magnesiumSulfate', lang)];
                aoa.push([t('week', lang), t('dateRangeHeader', lang), ...fNames.map(n => `${n} (kg/ha)`)]);
                weeklyPlan.forEach(w => {
                    aoa.push([w.week, getWeekDateRangeText(formData.sowingDate, w.week), parseFloat(w.nitrogen.toFixed(1)), parseFloat(w.phosphorus.toFixed(1)), parseFloat(w.potassium.toFixed(1)), parseFloat(w.calcium.toFixed(1)), parseFloat(w.magnesium.toFixed(1))]);
                });
                aoa.push([t('totalLabel', lang), '', parseFloat(totals.nitrogen.toFixed(1)), parseFloat(totals.phosphorus.toFixed(1)), parseFloat(totals.potassium.toFixed(1)), parseFloat(totals.calcium.toFixed(1)), parseFloat(totals.magnesium.toFixed(1))]);
            }
        }
    });

    const ws = XLSX.utils.aoa_to_sheet(aoa);
    ws['!cols'] = [ { wch: 35 }, { wch: 45 }, { wch: 25 }, { wch: 25 }, { wch: 25 }, { wch: 25 }, { wch: 25 } ];
    ws['!merges'] = getMergesForHeader(0);
    return ws;
};

export const generateXlsxReport = (reports: ReportData[], lang: Language) => {
    try {
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, generateSummarySheet(reports, lang), t('summarySheet', lang));
        XLSX.utils.book_append_sheet(wb, generateDetailsSheet(reports, lang), t('detailsSheet', lang));
        XLSX.writeFile(wb, "harvest_consulting_calculations.xlsx");
    } catch (e) {
        console.error("XLSX error", e);
        alert("Error generating file.");
    }
};

import React, { useState, useEffect, useRef } from 'react';
import type { CalculationResults, FormData, NutrientNeeds, CultureParams, SavedReport, BasicFertilizerSelections, ComplexFertilizer, SpringFertilizer } from './types';
import { Stepper } from './components/Stepper';
import { Step1SoilAnalysis } from './components/Step1SoilAnalysis';
import { Step2CropYield } from './components/Step2CropYield';
import { Step3CalculationChoice } from './components/Step3CalculationChoice';
import { Step4Results } from './components/Step4Results';
import { CULTURE_PARAMS } from './constants';
import { ReportsList } from './components/ReportsList';
import { ReportDetail } from './components/ReportDetail';
import { Logo } from './components/Logo';
import { generateTxtReport, generateXlsxReport } from './utils/reportGenerator';
import { t, Language } from './i18n';
import { SaveConfirmationModal } from './components/SaveConfirmationModal';
import { calculateNutrientNeeds } from './utils/nutrientCalculations';

const INITIAL_FORM_DATA: FormData = {
    culture: '',
    plannedYield: '',
    sowingDate: '',
    fieldArea: '1',
    fieldName: '',
    nitrogenAnalysis: '5',
    ph: '7.0',
    phosphorus: '50',
    potassium: '100',
    calcium: '2000',
    magnesium: '100',
    cec: '15',
    amendment: '',
};

const INITIAL_COMPLEX_FERTILIZER: ComplexFertilizer = {
    n: '', p2o5: '', k2o: '', cao: '', mg: '', rate: '', enabled: false
};

const INITIAL_SPRING_FERTILIZER: SpringFertilizer = {
    n: '', p: '', k: '', ca: '', mg: '', enabled: false
};

interface FertilizerSelections {
  springFertilizer: SpringFertilizer;
  nitrogenFertilizer: string;
  basicFertilizers: BasicFertilizerSelections;
  selectedAmendment: string;
  complexFertilizer: ComplexFertilizer;
  springFertilizerRate: number | null;
}

const INITIAL_FERTILIZER_SELECTIONS: FertilizerSelections = {
    springFertilizer: INITIAL_SPRING_FERTILIZER,
    nitrogenFertilizer: 'ammonium-nitrate',
    basicFertilizers: {},
    selectedAmendment: '',
    complexFertilizer: INITIAL_COMPLEX_FERTILIZER,
    springFertilizerRate: null,
};

function App() {
    const [mainView, setMainView] = useState<'landing' | 'calculator' | 'reports'>('landing');
    const [analysisMode, setAnalysisMode] = useState<'single' | 'group' | null>(null);
    const [currentStep, setCurrentStep] = useState(1);
    const [analyses, setAnalyses] = useState<FormData[]>([{...INITIAL_FORM_DATA, culture: 'Томат', plannedYield: '100'}]);
    const [activeAnalysisIndex, setActiveAnalysisIndex] = useState(0);

    const [results, setResults] = useState<CalculationResults | null>(null);
    const [groupResults, setGroupResults] = useState<(CalculationResults | null)[]>([]);
    const [calculationType, setCalculationType] = useState<'basic' | 'fertigation' | 'full' | null>(null);

    const [springFertilizer, setSpringFertilizer] = useState<SpringFertilizer>(INITIAL_SPRING_FERTILIZER);
    const [nitrogenFertilizer, setNitrogenFertilizer] = useState('ammonium-nitrate');
    const [basicFertilizers, setBasicFertilizers] = useState<BasicFertilizerSelections>({});
    const [selectedAmendment, setSelectedAmendment] = useState('');
    const [complexFertilizer, setComplexFertilizer] = useState<ComplexFertilizer>(INITIAL_COMPLEX_FERTILIZER);
    const [springFertilizerRate, setSpringFertilizerRate] = useState<number | null>(null);

    const [groupFertilizerSelections, setGroupFertilizerSelections] = useState<FertilizerSelections[]>([]);
    const [recordedIndices, setRecordedIndices] = useState<Set<number>>(new Set());
    const [isSaveModalOpen, setIsSaveModalOpen] = useState(false);

    const [language, setLanguage] = useState<Language>(() => {
        const savedLang = localStorage.getItem('agro-calc-lang');
        return (savedLang as Language) || 'uk';
    });

    const [isLangDropdownOpen, setIsLangDropdownOpen] = useState(false);
    const langDropdownRef = useRef<HTMLDivElement>(null);

    const [reports, setReports] = useState<SavedReport[]>(() => {
        try {
            const saved = localStorage.getItem('agro-reports');
            if (!saved) return [];
            return JSON.parse(saved);
        } catch (e) {
            return [];
        }
    });
    const [selectedReport, setSelectedReport] = useState<SavedReport | null>(null);
    const [customLogoUrl, setCustomLogoUrl] = useState<string | null>(localStorage.getItem('custom-logo'));
    const fileInputRef = useRef<HTMLInputElement>(null);
    const reportInputRef = useRef<HTMLInputElement>(null);

    const currentFormData = analyses[activeAnalysisIndex] || {...INITIAL_FORM_DATA};

    useEffect(() => {
        localStorage.setItem('agro-reports', JSON.stringify(reports));
    }, [reports]);

    useEffect(() => {
        localStorage.setItem('agro-calc-lang', language);
    }, [language]);

    const updateCurrentAnalysis = (data: Partial<FormData>) => {
        setAnalyses(prev => {
            const newAnalyses = [...prev];
            newAnalyses[activeAnalysisIndex] = { ...newAnalyses[activeAnalysisIndex], ...data };
            return newAnalyses;
        });
    };

    const handleNext = () => setCurrentStep(prev => prev + 1);
    const handleBack = () => setCurrentStep(prev => prev - 1);

    const handleCalculate = () => {
        setResults(calculateNutrientNeeds(currentFormData));
        setGroupResults([]);
        setCurrentStep(3);
    };

    const handleCalculateAll = () => {
        const allResults = analyses.map(f => calculateNutrientNeeds(f));
        setGroupResults(allResults);
        setGroupFertilizerSelections(analyses.map(() => ({ ...INITIAL_FERTILIZER_SELECTIONS })));
        setRecordedIndices(new Set(analyses.map((_, i) => i)));
        setResults(null);
        setCurrentStep(3);
    };

    const handleSelectCalculation = (type: 'basic' | 'fertigation' | 'full') => {
        setCalculationType(type);
        setCurrentStep(4);
    };

    const handleReset = () => {
        setCurrentStep(1);
        setAnalyses([{ ...INITIAL_FORM_DATA, culture: 'Томат', plannedYield: '100' }]);
        setActiveAnalysisIndex(0);
        setResults(null);
        setGroupResults([]);
        setCalculationType(null);
        setRecordedIndices(new Set());
        setMainView('landing');
        setAnalysisMode(null);
    };

    const handleSaveToHistory = () => {
        if (!results || !calculationType) return;
        const newReport: SavedReport = {
            id: Date.now().toString(),
            timestamp: new Date().toISOString(),
            formData: currentFormData,
            results: results!,
            calculationType: calculationType!,
            springFertilizer,
            nitrogenFertilizer,
            basicFertilizers,
            selectedAmendment,
            complexFertilizer,
            springFertilizerRate,
        };
        setReports(prev => [newReport, ...prev]);
        alert(t('saveToHistorySuccess', language));
    };

    const handleRecordCalculation = () => {
        setRecordedIndices(prev => {
            const next = new Set(prev);
            if (next.has(activeAnalysisIndex)) next.delete(activeAnalysisIndex);
            else next.add(activeAnalysisIndex);
            return next;
        });
    };

    const handleContinue = () => {
        setAnalyses(prev => [...prev, { ...INITIAL_FORM_DATA, culture: 'Томат', plannedYield: '100' }]);
        setActiveAnalysisIndex(analyses.length);
        setCurrentStep(1);
    };

    const handleOpenSaveModal = () => setIsSaveModalOpen(true);

    const handleConfirmSave = (selectedIndices: number[]) => {
        const reportsToSave = selectedIndices.map(index => {
            const formData = analyses[index];
            const result = groupResults[index];
            const selections = groupFertilizerSelections[index];
            if (!formData || !result || !selections || !calculationType) return null;
            return {
                formData,
                results: result,
                calculationType,
                cultureParams: CULTURE_PARAMS[formData.culture],
                springFertilizer: selections.springFertilizer,
                nitrogenFertilizer: selections.nitrogenFertilizer,
                basicFertilizers: selections.basicFertilizers,
                selectedAmendment: selections.selectedAmendment,
                complexFertilizer: selections.complexFertilizer,
                springFertilizerRate: selections.springFertilizerRate,
                lang: language
            };
        }).filter(Boolean);

        if (reportsToSave.length > 0) generateXlsxReport(reportsToSave as any, language);
        setIsSaveModalOpen(false);
    };

    return (
        <div className="container mx-auto p-4 md:p-8 font-sans bg-slate-50 min-h-screen">
            {isSaveModalOpen && (
                <SaveConfirmationModal
                    isOpen={isSaveModalOpen}
                    onClose={() => setIsSaveModalOpen(false)}
                    onConfirm={handleConfirmSave}
                    analyses={analyses}
                    recordedIndices={recordedIndices}
                    lang={language}
                />
            )}
            <input type="file" ref={fileInputRef} onChange={e => {
                const file = e.target.files?.[0];
                if (file) {
                    const reader = new FileReader();
                    reader.onloadend = () => {
                        const b64 = reader.result as string;
                        localStorage.setItem('custom-logo', b64);
                        setCustomLogoUrl(b64);
                    };
                    reader.readAsDataURL(file);
                }
            }} accept="image/*" className="hidden" />
            <input type="file" ref={reportInputRef} onChange={e => {
                const file = e.target.files?.[0];
                if (file) {
                    const reader = new FileReader();
                    reader.onload = e => {
                        try {
                            const data = JSON.parse(e.target?.result as string);
                            setReports(prev => [...(Array.isArray(data) ? data : [data]), ...prev]);
                            alert(t('reportLoadSuccessOne', language));
                        } catch (err) { alert(t('reportLoadError', language)); }
                    };
                    reader.readAsText(file);
                }
            }} className="hidden" />

            <header className="bg-gradient-to-r from-indigo-700 to-indigo-900 text-white p-4 md:p-6 rounded-xl shadow-2xl mb-10 flex justify-between items-center">
                <div className="flex items-center gap-4">
                     <div className="relative group cursor-pointer" onClick={() => fileInputRef.current?.click()}>
                        {customLogoUrl ? <img src={customLogoUrl} className="h-14 w-14 rounded-full object-cover" /> : <Logo className="h-14 w-14" />}
                    </div>
                    <div>
                        <h1 className="text-xl md:text-3xl font-bold">{t('headerTitle', language)}</h1>
                        <p className="text-indigo-200 hidden sm:block">Harvest Consulting</p>
                    </div>
                </div>
                <div className="flex items-center gap-4">
                     <button onClick={() => setMainView(mainView === 'reports' ? 'calculator' : 'reports')} className="bg-white/10 hover:bg-white/20 text-white font-semibold py-2 px-4 rounded-lg">
                        {mainView === 'reports' ? t('calculator', language) : t('reports', language)}
                    </button>
                </div>
            </header>

            {mainView === 'landing' && (
                <main className="bg-white p-12 rounded-xl shadow-lg text-center">
                    <h2 className="text-3xl font-bold text-slate-800">{t('landingTitle', language)}</h2>
                    <p className="mt-4 text-slate-600 max-w-2xl mx-auto">{t('landingDescription', language)}</p>
                    <div className="mt-10 flex flex-col sm:flex-row justify-center gap-6">
                        <button onClick={() => { setAnalysisMode('single'); setMainView('calculator'); }} className="bg-indigo-600 text-white font-bold py-4 px-8 rounded-lg">
                            {t('singleAnalysis', language)}
                        </button>
                        <button onClick={() => { setAnalysisMode('group'); setMainView('calculator'); }} className="bg-emerald-600 text-white font-bold py-4 px-8 rounded-lg">
                            {t('groupAnalysis', language)}
                        </button>
                    </div>
                </main>
            )}

            {mainView === 'calculator' && (
                <main className="bg-white p-6 rounded-xl shadow-lg">
                    {analysisMode === 'group' && (
                        <div className="mb-6 flex gap-2 overflow-x-auto pb-2 border-b">
                            {analyses.map((a, i) => (
                                <button key={i} onClick={() => setActiveAnalysisIndex(i)} className={`py-2 px-4 rounded-t-lg text-sm font-semibold ${activeAnalysisIndex === i ? 'bg-indigo-600 text-white' : 'text-slate-600 hover:bg-slate-200'}`}>
                                    {a.fieldName || t('analysisTab', language, { index: i + 1 })}
                                </button>
                            ))}
                            <button onClick={() => setAnalyses([...analyses, {...INITIAL_FORM_DATA}])} className="text-indigo-600 font-bold px-4">+</button>
                        </div>
                    )}
                    <Stepper currentStep={currentStep} steps={[t('step1', language), t('step2', language), t('step3', language), t('step4', language)]} />
                    <div className="mt-8">
                        {currentStep === 1 && <Step1SoilAnalysis onNext={handleNext} onBack={() => setMainView('landing')} data={currentFormData} onDataChange={updateCurrentAnalysis} lang={language} />}
                        {currentStep === 2 && <Step2CropYield onBack={handleBack} onCalculate={analysisMode === 'single' ? handleCalculate : handleCalculateAll} data={currentFormData} onDataChange={updateCurrentAnalysis} isGroupMode={analysisMode === 'group'} isCalculationDisabled={false} lang={language} />}
                        {currentStep === 3 && <Step3CalculationChoice onBack={handleBack} onSelect={handleSelectCalculation} lang={language} />}
                        {currentStep === 4 && (results || groupResults[activeAnalysisIndex]) && calculationType && (
                            <Step4Results 
                                onReset={handleReset} onBack={handleBack} results={(analysisMode === 'single' ? results : groupResults[activeAnalysisIndex])!}
                                type={calculationType!} formData={currentFormData} cultureParams={CULTURE_PARAMS[currentFormData.culture]}
                                onSaveToHistory={handleSaveToHistory} onSaveDownload={() => {}} 
                                springFertilizer={analysisMode === 'single' ? springFertilizer : groupFertilizerSelections[activeAnalysisIndex].springFertilizer}
                                setSpringFertilizer={analysisMode === 'single' ? setSpringFertilizer : (val) => setGroupFertilizerSelections(prev => { const next = [...prev]; next[activeAnalysisIndex].springFertilizer = typeof val === 'function' ? (val as any)(next[activeAnalysisIndex].springFertilizer) : val; return next; })}
                                nitrogenFertilizer={analysisMode === 'single' ? nitrogenFertilizer : groupFertilizerSelections[activeAnalysisIndex].nitrogenFertilizer}
                                setNitrogenFertilizer={analysisMode === 'single' ? setNitrogenFertilizer : (val) => setGroupFertilizerSelections(prev => { const next = [...prev]; next[activeAnalysisIndex].nitrogenFertilizer = typeof val === 'function' ? (val as any)(next[activeAnalysisIndex].nitrogenFertilizer) : val; return next; })}
                                basicFertilizers={analysisMode === 'single' ? basicFertilizers : groupFertilizerSelections[activeAnalysisIndex].basicFertilizers}
                                setBasicFertilizers={analysisMode === 'single' ? setBasicFertilizers : (val) => setGroupFertilizerSelections(prev => { const next = [...prev]; next[activeAnalysisIndex].basicFertilizers = typeof val === 'function' ? (val as any)(next[activeAnalysisIndex].basicFertilizers) : val; return next; })}
                                selectedAmendment={analysisMode === 'single' ? selectedAmendment : groupFertilizerSelections[activeAnalysisIndex].selectedAmendment}
                                setSelectedAmendment={analysisMode === 'single' ? setSelectedAmendment : (val) => setGroupFertilizerSelections(prev => { const next = [...prev]; next[activeAnalysisIndex].selectedAmendment = typeof val === 'function' ? (val as any)(next[activeAnalysisIndex].selectedAmendment) : val; return next; })}
                                complexFertilizer={analysisMode === 'single' ? complexFertilizer : groupFertilizerSelections[activeAnalysisIndex].complexFertilizer}
                                setComplexFertilizer={analysisMode === 'single' ? setComplexFertilizer : (val) => setGroupFertilizerSelections(prev => { const next = [...prev]; next[activeAnalysisIndex].complexFertilizer = typeof val === 'function' ? (val as any)(next[activeAnalysisIndex].complexFertilizer) : val; return next; })}
                                springFertilizerRate={analysisMode === 'single' ? springFertilizerRate : groupFertilizerSelections[activeAnalysisIndex].springFertilizerRate}
                                setSpringFertilizerRate={analysisMode === 'single' ? setSpringFertilizerRate : (val) => setGroupFertilizerSelections(prev => { const next = [...prev]; next[activeAnalysisIndex].springFertilizerRate = typeof val === 'function' ? (val as any)(next[activeAnalysisIndex].springFertilizerRate) : val; return next; })}
                                isGroupMode={analysisMode === 'group'} onSaveAllTxt={() => {}} lang={language}
                                onRecord={handleRecordCalculation} onOpenSaveModal={handleOpenSaveModal} onContinue={handleContinue} recordedIndices={recordedIndices} activeAnalysisIndex={activeAnalysisIndex}
                           />
                        )}
                    </div>
                </main>
            )}

            {mainView === 'reports' && (
                selectedReport ? <ReportDetail report={selectedReport} onBack={() => setSelectedReport(null)} lang={language} /> :
                <ReportsList reports={reports} onView={setSelectedReport} onDelete={id => setReports(reports.filter(r => r.id !== id))} onNewCalculation={handleReset} onLoadReport={() => reportInputRef.current?.click()} lang={language} />
            )}

            <footer className="text-center mt-12 text-slate-500 text-sm">
                <p>{t('footerText', language, { year: new Date().getFullYear() })}</p>
            </footer>
        </div>
    );
}

export default App;

import React, { useState, useEffect, useRef } from 'react';
import type { CalculationResults, FormData, NutrientNeeds, CultureParams, SavedReport, BasicFertilizerSelections, ComplexFertilizer, SpringFertilizer } from './types';
import { Stepper } from './components/Stepper';
import { Step1SoilAnalysis } from './components/Step1SoilAnalysis';
import { Step2CropYield } from './components/Step2CropYield';
import { Step3CalculationChoice } from './components/Step3CalculationChoice';
import { Step4Results } from './components/Step4Results';
import { CULTURE_PARAMS } from './constants';
import { ReportsList } from './components/ReportsList';
import { ReportDetail } from './components/ReportDetail';
import { Logo } from './components/Logo';
import { generateTxtReport, generateXlsxReport } from './utils/reportGenerator';
import { t, Language } from './i18n';
import { SaveConfirmationModal } from './components/SaveConfirmationModal';
import { calculateNutrientNeeds } from './utils/nutrientCalculations';

const INITIAL_FORM_DATA: FormData = {
    culture: '',
    plannedYield: '',
    sowingDate: '',
    fieldArea: '1',
    fieldName: '',
    nitrogenAnalysis: '5',
    ph: '7.0',
    phosphorus: '50',
    potassium: '100',
    calcium: '2000',
    magnesium: '100',
    cec: '15',
    amendment: '',
};

const INITIAL_COMPLEX_FERTILIZER: ComplexFertilizer = {
    n: '', p2o5: '', k2o: '', cao: '', mg: '', rate: '', enabled: false
};

const INITIAL_SPRING_FERTILIZER: SpringFertilizer = {
    n: '', p: '', k: '', ca: '', mg: '', enabled: false
};

interface FertilizerSelections {
  springFertilizer: SpringFertilizer;
  nitrogenFertilizer: string;
  basicFertilizers: BasicFertilizerSelections;
  selectedAmendment: string;
  complexFertilizer: ComplexFertilizer;
  springFertilizerRate: number | null;
}

const INITIAL_FERTILIZER_SELECTIONS: FertilizerSelections = {
    springFertilizer: INITIAL_SPRING_FERTILIZER,
    nitrogenFertilizer: 'ammonium-nitrate',
    basicFertilizers: {},
    selectedAmendment: '',
    complexFertilizer: INITIAL_COMPLEX_FERTILIZER,
    springFertilizerRate: null,
};

function App() {
    const [mainView, setMainView] = useState<'landing' | 'calculator' | 'reports'>('landing');
    const [analysisMode, setAnalysisMode] = useState<'single' | 'group' | null>(null);
    const [currentStep, setCurrentStep] = useState(1);
    const [analyses, setAnalyses] = useState<FormData[]>([{...INITIAL_FORM_DATA, culture: 'Томат', plannedYield: '100'}]);
    const [activeAnalysisIndex, setActiveAnalysisIndex] = useState(0);

    const [results, setResults] = useState<CalculationResults | null>(null);
    const [groupResults, setGroupResults] = useState<(CalculationResults | null)[]>([]);
    const [calculationType, setCalculationType] = useState<'basic' | 'fertigation' | 'full' | null>(null);

    const [springFertilizer, setSpringFertilizer] = useState<SpringFertilizer>(INITIAL_SPRING_FERTILIZER);
    const [nitrogenFertilizer, setNitrogenFertilizer] = useState('ammonium-nitrate');
    const [basicFertilizers, setBasicFertilizers] = useState<BasicFertilizerSelections>({});
    const [selectedAmendment, setSelectedAmendment] = useState('');
    const [complexFertilizer, setComplexFertilizer] = useState<ComplexFertilizer>(INITIAL_COMPLEX_FERTILIZER);
    const [springFertilizerRate, setSpringFertilizerRate] = useState<number | null>(null);

    const [groupFertilizerSelections, setGroupFertilizerSelections] = useState<FertilizerSelections[]>([]);
    const [recordedIndices, setRecordedIndices] = useState<Set<number>>(new Set());
    const [isSaveModalOpen, setIsSaveModalOpen] = useState(false);

    const [language, setLanguage] = useState<Language>(() => {
        const savedLang = localStorage.getItem('agro-calc-lang');
        return (savedLang as Language) || 'uk';
    });

    const [isLangDropdownOpen, setIsLangDropdownOpen] = useState(false);
    const langDropdownRef = useRef<HTMLDivElement>(null);

    const [reports, setReports] = useState<SavedReport[]>(() => {
        try {
            const saved = localStorage.getItem('agro-reports');
            if (!saved) return [];
            return JSON.parse(saved);
        } catch (e) {
            return [];
        }
    });
    const [selectedReport, setSelectedReport] = useState<SavedReport | null>(null);
    const [customLogoUrl, setCustomLogoUrl] = useState<string | null>(localStorage.getItem('custom-logo'));
    const fileInputRef = useRef<HTMLInputElement>(null);
    const reportInputRef = useRef<HTMLInputElement>(null);

    const currentFormData = analyses[activeAnalysisIndex] || {...INITIAL_FORM_DATA};

    useEffect(() => {
        localStorage.setItem('agro-reports', JSON.stringify(reports));
    }, [reports]);

    useEffect(() => {
        localStorage.setItem('agro-calc-lang', language);
    }, [language]);

    const updateCurrentAnalysis = (data: Partial<FormData>) => {
        setAnalyses(prev => {
            const newAnalyses = [...prev];
            newAnalyses[activeAnalysisIndex] = { ...newAnalyses[activeAnalysisIndex], ...data };
            return newAnalyses;
        });
    };

    const handleNext = () => setCurrentStep(prev => prev + 1);
    const handleBack = () => setCurrentStep(prev => prev - 1);

    const handleCalculate = () => {
        setResults(calculateNutrientNeeds(currentFormData));
        setGroupResults([]);
        setCurrentStep(3);
    };

    const handleCalculateAll = () => {
        const allResults = analyses.map(f => calculateNutrientNeeds(f));
        setGroupResults(allResults);
        setGroupFertilizerSelections(analyses.map(() => ({ ...INITIAL_FERTILIZER_SELECTIONS })));
        setRecordedIndices(new Set(analyses.map((_, i) => i)));
        setResults(null);
        setCurrentStep(3);
    };

    const handleSelectCalculation = (type: 'basic' | 'fertigation' | 'full') => {
        setCalculationType(type);
        setCurrentStep(4);
    };

    const handleReset = () => {
        setCurrentStep(1);
        setAnalyses([{ ...INITIAL_FORM_DATA, culture: 'Томат', plannedYield: '100' }]);
        setActiveAnalysisIndex(0);
        setResults(null);
        setGroupResults([]);
        setCalculationType(null);
        setRecordedIndices(new Set());
        setMainView('landing');
        setAnalysisMode(null);
    };

    const handleSaveToHistory = () => {
        if (!results || !calculationType) return;
        const newReport: SavedReport = {
            id: Date.now().toString(),
            timestamp: new Date().toISOString(),
            formData: currentFormData,
            results: results!,
            calculationType: calculationType!,
            springFertilizer,
            nitrogenFertilizer,
            basicFertilizers,
            selectedAmendment,
            complexFertilizer,
            springFertilizerRate,
        };
        setReports(prev => [newReport, ...prev]);
        alert(t('saveToHistorySuccess', language));
    };

    const handleRecordCalculation = () => {
        setRecordedIndices(prev => {
            const next = new Set(prev);
            if (next.has(activeAnalysisIndex)) next.delete(activeAnalysisIndex);
            else next.add(activeAnalysisIndex);
            return next;
        });
    };

    const handleContinue = () => {
        setAnalyses(prev => [...prev, { ...INITIAL_FORM_DATA, culture: 'Томат', plannedYield: '100' }]);
        setActiveAnalysisIndex(analyses.length);
        setCurrentStep(1);
    };

    const handleOpenSaveModal = () => setIsSaveModalOpen(true);

    const handleConfirmSave = (selectedIndices: number[]) => {
        const reportsToSave = selectedIndices.map(index => {
            const formData = analyses[index];
            const result = groupResults[index];
            const selections = groupFertilizerSelections[index];
            if (!formData || !result || !selections || !calculationType) return null;
            return {
                formData,
                results: result,
                calculationType,
                cultureParams: CULTURE_PARAMS[formData.culture],
                springFertilizer: selections.springFertilizer,
                nitrogenFertilizer: selections.nitrogenFertilizer,
                basicFertilizers: selections.basicFertilizers,
                selectedAmendment: selections.selectedAmendment,
                complexFertilizer: selections.complexFertilizer,
                springFertilizerRate: selections.springFertilizerRate,
                lang: language
            };
        }).filter(Boolean);

        if (reportsToSave.length > 0) generateXlsxReport(reportsToSave as any, language);
        setIsSaveModalOpen(false);
    };

    return (
        <div className="container mx-auto p-4 md:p-8 font-sans bg-slate-50 min-h-screen">
            {isSaveModalOpen && (
                <SaveConfirmationModal
                    isOpen={isSaveModalOpen}
                    onClose={() => setIsSaveModalOpen(false)}
                    onConfirm={handleConfirmSave}
                    analyses={analyses}
                    recordedIndices={recordedIndices}
                    lang={language}
                />
            )}
            <input type="file" ref={fileInputRef} onChange={e => {
                const file = e.target.files?.[0];
                if (file) {
                    const reader = new FileReader();
                    reader.onloadend = () => {
                        const b64 = reader.result as string;
                        localStorage.setItem('custom-logo', b64);
                        setCustomLogoUrl(b64);
                    };
                    reader.readAsDataURL(file);
                }
            }} accept="image/*" className="hidden" />
            <input type="file" ref={reportInputRef} onChange={e => {
                const file = e.target.files?.[0];
                if (file) {
                    const reader = new FileReader();
                    reader.onload = e => {
                        try {
                            const data = JSON.parse(e.target?.result as string);
                            setReports(prev => [...(Array.isArray(data) ? data : [data]), ...prev]);
                            alert(t('reportLoadSuccessOne', language));
                        } catch (err) { alert(t('reportLoadError', language)); }
                    };
                    reader.readAsText(file);
                }
            }} className="hidden" />

            <header className="bg-gradient-to-r from-indigo-700 to-indigo-900 text-white p-4 md:p-6 rounded-xl shadow-2xl mb-10 flex justify-between items-center">
                <div className="flex items-center gap-4">
                     <div className="relative group cursor-pointer" onClick={() => fileInputRef.current?.click()}>
                        {customLogoUrl ? <img src={customLogoUrl} className="h-14 w-14 rounded-full object-cover" /> : <Logo className="h-14 w-14" />}
                    </div>
                    <div>
                        <h1 className="text-xl md:text-3xl font-bold">{t('headerTitle', language)}</h1>
                        <p className="text-indigo-200 hidden sm:block">Harvest Consulting</p>
                    </div>
                </div>
                <div className="flex items-center gap-4">
                     <button onClick={() => setMainView(mainView === 'reports' ? 'calculator' : 'reports')} className="bg-white/10 hover:bg-white/20 text-white font-semibold py-2 px-4 rounded-lg">
                        {mainView === 'reports' ? t('calculator', language) : t('reports', language)}
                    </button>
                </div>
            </header>

            {mainView === 'landing' && (
                <main className="bg-white p-12 rounded-xl shadow-lg text-center">
                    <h2 className="text-3xl font-bold text-slate-800">{t('landingTitle', language)}</h2>
                    <p className="mt-4 text-slate-600 max-w-2xl mx-auto">{t('landingDescription', language)}</p>
                    <div className="mt-10 flex flex-col sm:flex-row justify-center gap-6">
                        <button onClick={() => { setAnalysisMode('single'); setMainView('calculator'); }} className="bg-indigo-600 text-white font-bold py-4 px-8 rounded-lg">
                            {t('singleAnalysis', language)}
                        </button>
                        <button onClick={() => { setAnalysisMode('group'); setMainView('calculator'); }} className="bg-emerald-600 text-white font-bold py-4 px-8 rounded-lg">
                            {t('groupAnalysis', language)}
                        </button>
                    </div>
                </main>
            )}

            {mainView === 'calculator' && (
                <main className="bg-white p-6 rounded-xl shadow-lg">
                    {analysisMode === 'group' && (
                        <div className="mb-6 flex gap-2 overflow-x-auto pb-2 border-b">
                            {analyses.map((a, i) => (
                                <button key={i} onClick={() => setActiveAnalysisIndex(i)} className={`py-2 px-4 rounded-t-lg text-sm font-semibold ${activeAnalysisIndex === i ? 'bg-indigo-600 text-white' : 'text-slate-600 hover:bg-slate-200'}`}>
                                    {a.fieldName || t('analysisTab', language, { index: i + 1 })}
                                </button>
                            ))}
                            <button onClick={() => setAnalyses([...analyses, {...INITIAL_FORM_DATA}])} className="text-indigo-600 font-bold px-4">+</button>
                        </div>
                    )}
                    <Stepper currentStep={currentStep} steps={[t('step1', language), t('step2', language), t('step3', language), t('step4', language)]} />
                    <div className="mt-8">
                        {currentStep === 1 && <Step1SoilAnalysis onNext={handleNext} onBack={() => setMainView('landing')} data={currentFormData} onDataChange={updateCurrentAnalysis} lang={language} />}
                        {currentStep === 2 && <Step2CropYield onBack={handleBack} onCalculate={analysisMode === 'single' ? handleCalculate : handleCalculateAll} data={currentFormData} onDataChange={updateCurrentAnalysis} isGroupMode={analysisMode === 'group'} isCalculationDisabled={false} lang={language} />}
                        {currentStep === 3 && <Step3CalculationChoice onBack={handleBack} onSelect={handleSelectCalculation} lang={language} />}
                        {currentStep === 4 && (results || groupResults[activeAnalysisIndex]) && calculationType && (
                            <Step4Results 
                                onReset={handleReset} onBack={handleBack} results={(analysisMode === 'single' ? results : groupResults[activeAnalysisIndex])!}
                                type={calculationType!} formData={currentFormData} cultureParams={CULTURE_PARAMS[currentFormData.culture]}
                                onSaveToHistory={handleSaveToHistory} onSaveDownload={() => {}} 
                                springFertilizer={analysisMode === 'single' ? springFertilizer : groupFertilizerSelections[activeAnalysisIndex].springFertilizer}
                                setSpringFertilizer={analysisMode === 'single' ? setSpringFertilizer : (val) => setGroupFertilizerSelections(prev => { const next = [...prev]; next[activeAnalysisIndex].springFertilizer = typeof val === 'function' ? (val as any)(next[activeAnalysisIndex].springFertilizer) : val; return next; })}
                                nitrogenFertilizer={analysisMode === 'single' ? nitrogenFertilizer : groupFertilizerSelections[activeAnalysisIndex].nitrogenFertilizer}
                                setNitrogenFertilizer={analysisMode === 'single' ? setNitrogenFertilizer : (val) => setGroupFertilizerSelections(prev => { const next = [...prev]; next[activeAnalysisIndex].nitrogenFertilizer = typeof val === 'function' ? (val as any)(next[activeAnalysisIndex].nitrogenFertilizer) : val; return next; })}
                                basicFertilizers={analysisMode === 'single' ? basicFertilizers : groupFertilizerSelections[activeAnalysisIndex].basicFertilizers}
                                setBasicFertilizers={analysisMode === 'single' ? setBasicFertilizers : (val) => setGroupFertilizerSelections(prev => { const next = [...prev]; next[activeAnalysisIndex].basicFertilizers = typeof val === 'function' ? (val as any)(next[activeAnalysisIndex].basicFertilizers) : val; return next; })}
                                selectedAmendment={analysisMode === 'single' ? selectedAmendment : groupFertilizerSelections[activeAnalysisIndex].selectedAmendment}
                                setSelectedAmendment={analysisMode === 'single' ? setSelectedAmendment : (val) => setGroupFertilizerSelections(prev => { const next = [...prev]; next[activeAnalysisIndex].selectedAmendment = typeof val === 'function' ? (val as any)(next[activeAnalysisIndex].selectedAmendment) : val; return next; })}
                                complexFertilizer={analysisMode === 'single' ? complexFertilizer : groupFertilizerSelections[activeAnalysisIndex].complexFertilizer}
                                setComplexFertilizer={analysisMode === 'single' ? setComplexFertilizer : (val) => setGroupFertilizerSelections(prev => { const next = [...prev]; next[activeAnalysisIndex].complexFertilizer = typeof val === 'function' ? (val as any)(next[activeAnalysisIndex].complexFertilizer) : val; return next; })}
                                springFertilizerRate={analysisMode === 'single' ? springFertilizerRate : groupFertilizerSelections[activeAnalysisIndex].springFertilizerRate}
                                setSpringFertilizerRate={analysisMode === 'single' ? setSpringFertilizerRate : (val) => setGroupFertilizerSelections(prev => { const next = [...prev]; next[activeAnalysisIndex].springFertilizerRate = typeof val === 'function' ? (val as any)(next[activeAnalysisIndex].springFertilizerRate) : val; return next; })}
                                isGroupMode={analysisMode === 'group'} onSaveAllTxt={() => {}} lang={language}
                                onRecord={handleRecordCalculation} onOpenSaveModal={handleOpenSaveModal} onContinue={handleContinue} recordedIndices={recordedIndices} activeAnalysisIndex={activeAnalysisIndex}
                           />
                        )}
                    </div>
                </main>
            )}

            {mainView === 'reports' && (
                selectedReport ? <ReportDetail report={selectedReport} onBack={() => setSelectedReport(null)} lang={language} /> :
                <ReportsList reports={reports} onView={setSelectedReport} onDelete={id => setReports(reports.filter(r => r.id !== id))} onNewCalculation={handleReset} onLoadReport={() => reportInputRef.current?.click()} lang={language} />
            )}

            <footer className="text-center mt-12 text-slate-500 text-sm">
                <p>{t('footerText', language, { year: new Date().getFullYear() })}</p>
            </footer>
        </div>
    );
}

