];

export const generateTxtReport = (data: ReportData): string => {
    const { formData, results, calculationType, complexFertilizer, lang } = data;
    const cultureName = CULTURES.find(c => c.key === formData.culture)?.name[lang] || formData.culture;
    let report = `==================================================\n   HarvestConsulting\n==================================================\n\n   ${t('resultsTitle', lang, { cultureName })}\n\n`;
    if (calculationType !== 'fertigation') {
        report += `---------- ${t('basicApplicationSection', lang)} ----------\n`;
        if (complexFertilizer?.enabled && parseFloat(complexFertilizer.rate) > 0) {
            report += `${getNormalizedFertName(complexFertilizer.n, complexFertilizer.p2o5, complexFertilizer.k2o, complexFertilizer.cao, complexFertilizer.mg, t('complexFertilizer', lang), lang)}: ${complexFertilizer.rate} kg/ha\n`;
        }
    }
    return report;
};

const addValueToProcurement = (procurement: Record<string, number>, key: string, value: number) => {
    if (!key || isNaN(value) || value <= 0) return;
    const normKey = key.trim();
    procurement[normKey] = (procurement[normKey] || 0) + value;
};

const generateSummarySheet = (reports: ReportData[], lang: Language) => {
    const preSeasonTotals: Record<string, number> = {};
    const monthlyTotals: Record<string, Record<string, number>> = {};

    reports.forEach(report => {
        const { formData, results, cultureParams, springFertilizer, nitrogenFertilizer, complexFertilizer, basicFertilizers, selectedAmendment, springFertilizerRate } = report;
        const area = parseFloat(formData.fieldArea) || 1;

        if (complexFertilizer?.enabled && parseFloat(complexFertilizer.rate) > 0) {
            addValueToProcurement(preSeasonTotals, getNormalizedFertName(complexFertilizer.n, complexFertilizer.p2o5, complexFertilizer.k2o, complexFertilizer.cao, complexFertilizer.mg, t('complexFertilizer', lang), lang), parseFloat(complexFertilizer.rate) * area);
        }
        if (springFertilizer?.enabled && springFertilizerRate && springFertilizerRate > 0) {
            addValueToProcurement(preSeasonTotals, getNormalizedFertName(springFertilizer.n, springFertilizer.p, springFertilizer.k, springFertilizer.ca, springFertilizer.mg, t('springFertilizer', lang), lang), springFertilizerRate * area);
        }

        let basicNeeds = [...results.basic];

        if (selectedAmendment && parseFloat(formData.ph) <= 6.8) {
            const phVal = parseFloat(formData.ph);
            const amendmentRateTons = Math.round((7 - phVal) * 5);
            addValueToProcurement(preSeasonTotals, AMENDMENTS.find(a => a.value === selectedAmendment)?.label[lang] || selectedAmendment, amendmentRateTons * 1000 * area);
            const effect = AMENDMENT_EFFECTS[selectedAmendment as keyof typeof AMENDMENT_EFFECTS];
            if (effect) {
                const caSupplied = effect.calcium * amendmentRateTons;
                const mgSupplied = effect.magnesium * amendmentRateTons;
                basicNeeds = basicNeeds.map(n => {
                    if (n.element === 'CaO') return { ...n, norm: Math.max(0, n.norm - caSupplied) };
                    if (n.element === 'MgO') return { ...n, norm: Math.max(0, n.norm - mgSupplied) };
                    return n;
                });
            }
        }

        if (complexFertilizer?.enabled && parseFloat(complexFertilizer.rate) > 0) {
            const r = parseFloat(complexFertilizer.rate);
            const sup = { 
                'P2O5': r * (parseFloat(complexFertilizer.p2o5||'0')/100), 
                'K2O': r * (parseFloat(complexFertilizer.k2o||'0')/100), 
                'CaO': r * (parseFloat(complexFertilizer.cao||'0')/100), 
                'MgO': r * (parseFloat(complexFertilizer.mg||'0')/100) 
            };
            basicNeeds = basicNeeds.map(n => ({ ...n, norm: Math.max(0, n.norm - (sup[n.element as keyof typeof sup] || 0)) }));
        }

        Object.keys(basicFertilizers).forEach(el => {
            const fert = SIMPLE_FERTILIZERS[el]?.find(f => f.value.toString() === basicFertilizers[el]?.selectedFertilizer);
            const n = basicNeeds.find(n => n.element === el)?.norm || 0;
            if (fert && n > 0) addValueToProcurement(preSeasonTotals, fert.label[lang], (n / fert.value) * 100 * area);
        });

        const cKey = Object.keys(FERTIGATION_CULTURES).find(k => FERTIGATION_CULTURES[k].startsWith(results.culture));
        if (cKey) {
            const { weeklyPlan } = calculateFertigationPlan({ initialNeeds: results.fertigation, cultureKey: cKey, cultureParams, springFertilizer, nitrogenFertilizer, manualRate: springFertilizerRate });
            const fNames = [nitrogenFertilizer === 'urea' ? t('urea', lang) : t('ammoniumNitrate', lang), t('phosphoricAcid', lang), t('potassiumSulfate', lang), t('calciumNitrate', lang), t('magnesiumSulfate', lang)];
            const baseDate = formData.sowingDate ? new Date(formData.sowingDate) : new Date();
            weeklyPlan.forEach(w => {
                const m = t(`month_${new Date(baseDate.getTime() + (w.week-1)*7*24*60*60*1000).getMonth()}` as TranslationKey, lang);
                [w.nitrogen, w.phosphorus, w.potassium, w.calcium, w.magnesium].forEach((v, i) => {
                    if (v > 0) {
                        if (!monthlyTotals[fNames[i]]) monthlyTotals[fNames[i]] = {};
                        monthlyTotals[fNames[i]][m] = (monthlyTotals[fNames[i]][m] || 0) + v * area;
                    }
                });
            });
        }
    });

    const preData = Object.entries(preSeasonTotals).map(([name, totalVal]) => ({ 
        [t('fertilizerNameHeader', lang)]: name, 
        [t('totalNeededKgHeader', lang)]: parseFloat(totalVal.toFixed(1)),
        "Unit": "kg"
    }));

    const months = [...new Set(Object.values(monthlyTotals).flatMap(m => Object.keys(m)))].sort((a,b) => {
        const o = Array.from({length:12}, (_,i)=>t(`month_${i}` as TranslationKey, lang));
        return o.indexOf(a) - o.indexOf(b);
    });

    const monData = Object.keys(monthlyTotals).sort().map(f => {
        const row: any = { [t('fertilizerNameHeader', lang)]: f };
        let s = 0;
        months.forEach(m => { 
            const v = monthlyTotals[f][m] || 0; 
            row[m] = v > 0 ? parseFloat(v.toFixed(1)) : ''; 
            s += v; 
        });
        row[t('totalLabel', lang)] = parseFloat(s.toFixed(1));
        row["Unit"] = "kg";
        return row;
    });

    let aoa: any[][] = [];
    addCorporateHeader(aoa, t('summarySheet', lang));

    const ws = XLSX.utils.aoa_to_sheet(aoa);

    // Add sections with visual padding
    let currentLastRow = aoa.length;
    XLSX.utils.sheet_add_aoa(ws, [[t('preSeasonFertilizersHeader', lang).toUpperCase()]], { origin: `A${currentLastRow + 1}` });
    XLSX.utils.sheet_add_json(ws, preData, { origin: `A${currentLastRow + 2}`, skipHeader: false });

    currentLastRow += preData.length + 5;
    XLSX.utils.sheet_add_aoa(ws, [[t('monthlyNeedsHeader', lang).toUpperCase()]], { origin: `A${currentLastRow}` });
    XLSX.utils.sheet_add_json(ws, monData, { origin: `A${currentLastRow + 1}`, skipHeader: false });

    ws['!cols'] = [{ wch: 50 }, ...months.map(() => ({ wch: 12 })), { wch: 15 }, { wch: 8 }];
    ws['!merges'] = getMergesForHeader(0);
    return ws;
};

const generateDetailsSheet = (reports: ReportData[], lang: Language) => {
    let aoa: any[][] = [];
    addCorporateHeader(aoa, t('detailsSheet', lang));

    reports.forEach((report, idx) => {
        const { formData, results, cultureParams, springFertilizer, nitrogenFertilizer, complexFertilizer, basicFertilizers, selectedAmendment, springFertilizerRate } = report;
        const area = parseFloat(formData.fieldArea) || 1;
        const cultureName = CULTURES.find(c => c.key === formData.culture)?.name[lang] || formData.culture;

        if (idx > 0) { aoa.push([], [], ["================================================================================================="], []); }

        aoa.push([`ОБ'ЄКТ: ${formData.fieldName || 'Поле ' + (idx+1)}`]);
        aoa.push([`${t('cultureLabel', lang)}: ${cultureName}`, `${t('fieldAreaLabel', lang)}: ${area} ha`, `${t('plannedYieldLabel', lang)}: ${formData.plannedYield} t/ha`]);
        aoa.push([`Аналіз ґрунту: pH=${formData.ph}, ЄКО=${formData.cec}, N=${formData.nitrogenAnalysis}, P2O5=${formData.phosphorus}, K2O=${formData.potassium}, CaO=${formData.calcium}, MgO=${formData.magnesium}`]);

        if (report.calculationType !== 'fertigation') {
            aoa.push([], [t('basicApplicationSection', lang).toUpperCase()], [t('fertilizerTypeHeader', lang), t('fertilizerNameCompositionHeader', lang), `${t('applicationRate', lang)} (kg/ha)`, `${t('totalLabel', lang)} (kg)`]);

            let needs = [...results.basic];

            if (selectedAmendment && parseFloat(formData.ph) <= 6.8) {
                const phVal = parseFloat(formData.ph);
                const r = Math.round((7 - phVal) * 5) * 1000;
                aoa.push([t('amendmentLabel', lang), AMENDMENTS.find(a => a.value === selectedAmendment)?.label[lang] || selectedAmendment, r, r * area]);
                const effect = AMENDMENT_EFFECTS[selectedAmendment as keyof typeof AMENDMENT_EFFECTS];
                if (effect) {
                    needs = needs.map(n => {
                        if (n.element === 'CaO') return { ...n, norm: Math.max(0, n.norm - effect.calcium * Math.round((7 - phVal) * 5)) };
                        if (n.element === 'MgO') return { ...n, norm: Math.max(0, n.norm - effect.magnesium * Math.round((7 - phVal) * 5)) };
                        return n;
                    });
                }
            }

            if (complexFertilizer?.enabled && parseFloat(complexFertilizer.rate) > 0) {
                const n = getNormalizedFertName(complexFertilizer.n, complexFertilizer.p2o5, complexFertilizer.k2o, complexFertilizer.cao, complexFertilizer.mg, t('complexFertilizer', lang), lang);
                const r = parseFloat(complexFertilizer.rate);
                aoa.push([t('complexFertilizer', lang), n, r, r * area]);
                const sup = { 
                    'P2O5': r * (parseFloat(complexFertilizer.p2o5||'0')/100), 
                    'K2O': r * (parseFloat(complexFertilizer.k2o||'0')/100), 
                    'CaO': r * (parseFloat(complexFertilizer.cao||'0')/100), 
                    'MgO': r * (parseFloat(complexFertilizer.mg||'0')/100) 
                };
                needs = needs.map(n => ({ ...n, norm: Math.max(0, n.norm - (sup[n.element as keyof typeof sup] || 0)) }));
            }

            needs.filter(n => n.element !== 'Меліорант' && n.norm > 0).forEach(n => {
                const f = SIMPLE_FERTILIZERS[n.element]?.find(f => f.value.toString() === basicFertilizers[n.element]?.selectedFertilizer);
                if (f) {
                    const r = (n.norm / f.value) * 100;
                    aoa.push([`${t('fertilizerLabel', lang)} (${n.element})`, f.label[lang], parseFloat(r.toFixed(1)), parseFloat((r * area).toFixed(1))]);
                }
            });
        }

        if (report.calculationType !== 'basic') {
            aoa.push([], [t('fertigationProgramSection', lang).toUpperCase()]);
            if (springFertilizer?.enabled && springFertilizerRate && springFertilizerRate > 0) {
                const n = getNormalizedFertName(springFertilizer.n, springFertilizer.p, springFertilizer.k, springFertilizer.ca, springFertilizer.mg, t('springFertilizer', lang), lang);
                aoa.push([t('springFertilizer', lang), n, springFertilizerRate, springFertilizerRate * area]);
            }
            const cK = Object.keys(FERTIGATION_CULTURES).find(k => FERTIGATION_CULTURES[k].startsWith(results.culture));
            if (cK) {
                const { weeklyPlan, totals } = calculateFertigationPlan({ initialNeeds: results.fertigation, cultureKey: cK, cultureParams, springFertilizer, nitrogenFertilizer, manualRate: springFertilizerRate });
                const fNs = [nitrogenFertilizer === 'urea' ? t('urea', lang) : t('ammoniumNitrate', lang), t('phosphoricAcid', lang), t('potassiumSulfate', lang), t('calciumNitrate', lang), t('magnesiumSulfate', lang)];

                aoa.push([], [t('week', lang), t('dateRangeHeader', lang), ...fNs.map(n => `${n} (kg/ha)`)]);
                weeklyPlan.forEach(w => {
                    const row = [w.week, getWeekDateRangeText(formData.sowingDate, w.week)];
                    [w.nitrogen, w.phosphorus, w.potassium, w.calcium, w.magnesium].forEach(v => row.push(v > 0 ? parseFloat(v.toFixed(1)) : ''));
                    aoa.push(row);
                });
                aoa.push([t('totalLabel', lang), '', parseFloat(totals.nitrogen.toFixed(1)), parseFloat(totals.phosphorus.toFixed(1)), parseFloat(totals.potassium.toFixed(1)), parseFloat(totals.calcium.toFixed(1)), parseFloat(totals.magnesium.toFixed(1))]);
            }
        }
    });

    const ws = XLSX.utils.aoa_to_sheet(aoa);
    ws['!cols'] = [{ wch: 30 }, { wch: 45 }, { wch: 15 }, { wch: 15 }, { wch: 15 }, { wch: 15 }, { wch: 15 }, { wch: 15 }];
    ws['!merges'] = getMergesForHeader(0);
    return ws;
};

export const generateXlsxReport = (reports: ReportData[], lang: Language) => {
    try {
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, generateSummarySheet(reports, lang), t('summarySheet', lang));
        XLSX.utils.book_append_sheet(wb, generateDetailsSheet(reports, lang), t('detailsSheet', lang));
        XLSX.writeFile(wb, "HarvestConsulting_Fertilizer_Plan.xlsx");
    } catch (e) { console.error(e); alert("XLSX error"); }
};

import React from 'react';
import type { CalculationResults, FormData, CultureParams, BasicFertilizerSelections, ComplexFertilizer, SpringFertilizer } from '../types';
import { BasicApplicationCalculator } from './BasicApplicationCalculator';
import { FertigationProgram } from './FertigationProgram';
import { generateTxtReport } from '../utils/reportGenerator';
import { DropdownButton, DropdownAction } from './SaveButtonDropdown';
import { Language, t } from '../i18n';
import { CULTURES } from '../constants';

interface Step4Props {
    onReset: () => void;
    onBack: () => void;
    results: CalculationResults;
    type: 'basic' | 'fertigation' | 'full';
    formData: FormData;
    cultureParams: CultureParams;
    onSaveToHistory: () => void;
    onSaveDownload: () => void;
    springFertilizer: SpringFertilizer;
    setSpringFertilizer: React.Dispatch<React.SetStateAction<SpringFertilizer>>;
    nitrogenFertilizer: string;
    setNitrogenFertilizer: React.Dispatch<React.SetStateAction<string>>;
    basicFertilizers: BasicFertilizerSelections;
    setBasicFertilizers: React.Dispatch<React.SetStateAction<BasicFertilizerSelections>>;
    selectedAmendment: string;
    setSelectedAmendment: React.Dispatch<React.SetStateAction<string>>;
    complexFertilizer: ComplexFertilizer;
    setComplexFertilizer: React.Dispatch<React.SetStateAction<ComplexFertilizer>>;
    springFertilizerRate: number | null;
    setSpringFertilizerRate: (rate: number | null) => void;
    isGroupMode: boolean;
    onSaveAllTxt: () => void;
    lang: Language;
    // New optional props for group mode
    onRecord?: () => void;
    onOpenSaveModal?: () => void;
    onContinue?: () => void;
    recordedIndices?: Set<number>;
    activeAnalysisIndex?: number;
}

const SaveReportIcon = () => (
     <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M5 4h14a1 1 0 011 1v14a1 1 0 01-1 1H5a1 1 0 01-1-1V5a1 1 0 011-1z" />
        <path strokeLinecap="round" strokeLinejoin="round" d="M15 8H9" />
        <path strokeLinecap="round" strokeLinejoin="round" d="M9 12h3" />
    </svg>
);

const HistoryIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
    </svg>
);

const PlusIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M12 4v16m8-8H4" />
    </svg>
);

export const Step4Results: React.FC<Step4Props> = ({ 
    onReset, 
    onBack,
    results, 
    type, 
    formData, 
    cultureParams,
    onSaveToHistory,
    onSaveDownload,
    springFertilizer,
    setSpringFertilizer,
    nitrogenFertilizer,
    setNitrogenFertilizer,
    basicFertilizers,
    setBasicFertilizers,
    selectedAmendment,
    setSelectedAmendment,
    complexFertilizer,
    setComplexFertilizer,
    springFertilizerRate,
    setSpringFertilizerRate,
    isGroupMode,
    onSaveAllTxt,
    lang,
    onRecord,
    onOpenSaveModal,
    onContinue,
    recordedIndices,
    activeAnalysisIndex,
}) => {

    const showBasic = type === 'basic' || type === 'full';
    const showFertigation = type === 'fertigation' || type === 'full';

    const handleSaveTxt = () => {
        const reportContent = generateTxtReport({
            formData,
            results,
            calculationType: type,
            cultureParams,
            springFertilizer,
            nitrogenFertilizer,
            complexFertilizer,
            basicFertilizers,
            selectedAmendment,
            springFertilizerRate,
            lang,
        });

        const blob = new Blob([reportContent], { type: 'text/plain;charset=utf-8' });
        const link = document.createElement('a');
        const url = URL.createObjectURL(blob);
        const fieldName = formData.fieldName ? `${formData.fieldName}_` : '';
        link.setAttribute('href', url);
        link.setAttribute('download', `calculation_${fieldName}${formData.culture}.txt`);
        link.style.visibility = 'hidden';
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
    };

    const saveActions: DropdownAction[] = [
        {
            label: isGroupMode ? t('saveAllJsonAction', lang) : t('saveJsonAction', lang),
            onClick: onSaveDownload,
            iconType: 'json',
        },
        {
            label: t('saveTxtAction', lang),
            onClick: handleSaveTxt,
            iconType: 'txt',
        }
    ];

    const cultureName = CULTURES.find(c => c.key === results.culture)?.name[lang] || results.culture;

    const isRecorded = isGroupMode && recordedIndices?.has(activeAnalysisIndex!);
    const hasRecordings = isGroupMode && recordedIndices && recordedIndices.size > 0;

    return (
        <div className="space-y-10">
            <h2 className="text-3xl font-bold text-center text-slate-800 mb-6">
                {t('resultsTitle', lang, { cultureName: formData.fieldName || cultureName })}
            </h2>

            <div className="space-y-10">
                {showBasic && (
                    <div className="bg-white p-6 rounded-lg shadow-md border border-slate-100">
                       <BasicApplicationCalculator 
                           needs={results.basic} 
                           formData={formData}
                           selections={basicFertilizers}
                           onSelectionsChange={setBasicFertilizers}
                           amendment={selectedAmendment}
                           onAmendmentChange={setSelectedAmendment}
                           complexFertilizer={complexFertilizer}
                           onComplexFertilizerChange={setComplexFertilizer}
                           lang={lang}
                        />
                    </div>
                )}
                {showFertigation && (
                    <div className="bg-white p-6 rounded-lg shadow-md border border-slate-100">
                        <FertigationProgram 
                            initialNeeds={results.fertigation} 
                            culture={results.culture}
                            cultureParams={cultureParams}
                            formData={formData}
                            springFertilizer={springFertilizer}
                            setSpringFertilizer={setSpringFertilizer}
                            nitrogenFertilizer={nitrogenFertilizer}
                            setNitrogenFertilizer={setNitrogenFertilizer}
                            springFertilizerRate={springFertilizerRate}
                            setSpringFertilizerRate={setSpringFertilizerRate}
                            lang={lang}
                            isGroupMode={isGroupMode}
                        />
                    </div>
                )}
            </div>

            <div className="flex flex-col sm:flex-row justify-between items-center gap-4 pt-8 border-t mt-10">
                <div className="flex flex-col sm:flex-row gap-4 w-full sm:w-auto">
                    <button
                        onClick={onBack}
                        className="w-full sm:w-auto flex items-center justify-center gap-2 bg-slate-300 text-slate-800 font-semibold py-3 px-6 rounded-lg hover:bg-slate-400 transition-colors duration-300"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
                        <span>{t('backButton', lang)}</span>
                    </button>
                    {!isGroupMode && (
                        <button
                            onClick={onReset}
                            className="w-full sm:w-auto flex items-center justify-center gap-2 bg-slate-200 text-slate-700 font-semibold py-3 px-6 rounded-lg hover:bg-slate-300 transition-colors duration-300"
                        >
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                                <path strokeLinecap="round" strokeLinejoin="round" d="M16.023 9.348h4.992v-.001M2.985 19.644v-4.992m0 0h4.992m-4.993 0l3.181 3.183a8.25 8.25 0 0011.667 0l3.181-3.183m-4.991-2.695V7.5a8.25 8.25 0 00-16.5 0v2.694" />
                            </svg>
                            <span>{t('newCalculationButton', lang)}</span>
                        </button>
                    )}
                </div>
                <div className="flex flex-col sm:flex-row gap-4 w-full sm:w-auto">
                   {isGroupMode ? (
                        <div className="flex flex-col sm:flex-row gap-4 w-full">
                            {onContinue && (
                                <button
                                    onClick={onContinue}
                                    className="w-full sm:w-auto flex items-center justify-center gap-2 bg-slate-200 text-slate-700 font-semibold py-3 px-6 rounded-lg hover:bg-slate-300 transition-colors duration-300"
                                >
                                    <PlusIcon />
                                    <span>{t('continueButton', lang)}</span>
                                </button>
                            )}
                            {onRecord && (
                                <button
                                    onClick={onRecord}
                                    className={`w-full sm:w-auto flex items-center justify-center gap-2 font-semibold py-3 px-6 rounded-lg transition-colors duration-300 ${
                                        isRecorded 
                                        ? 'bg-emerald-100 text-emerald-700 border border-emerald-300' 
                                        : 'bg-emerald-600 text-white hover:bg-emerald-700 shadow-md ring-4 ring-emerald-500/20'
                                    }`}
                                >
                                    <SaveReportIcon />
                                    <span>{isRecorded ? t('recordedButton', lang) : t('recordButton', lang)}</span>
                                </button>
                            )}
                            <DropdownButton 
                                actions={saveActions} 
                                buttonLabel={t('saveReportButton', lang)}
                                buttonIcon={<SaveReportIcon />}
                            />
                            {onOpenSaveModal && (
                                <button
                                    onClick={onOpenSaveModal}
                                    className={`w-full sm:w-auto flex items-center justify-center gap-2 font-bold py-3 px-6 rounded-lg transition duration-300 shadow-lg text-lg ${
                                      hasRecordings 
                                      ? 'bg-indigo-600 text-white hover:bg-indigo-700 ring-4 ring-indigo-500/20' 
                                      : 'bg-slate-300 text-slate-500 cursor-not-allowed'
                                    }`}
                                    disabled={!hasRecordings}
                                >
                                     <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                                    <span>{t('saveXlsxButton', lang, { count: recordedIndices?.size || 0 })}</span>
                                </button>
                            )}
                        </div>
                    ) : (
                        <div className="flex flex-col sm:flex-row gap-4">
                            <button
                                onClick={onSaveToHistory}
                                className="flex items-center justify-center gap-2 bg-indigo-600 text-white font-bold py-3 px-6 rounded-lg hover:bg-indigo-700 transition-colors duration-300 shadow-md ring-4 ring-indigo-500/20"
                            >
                                <HistoryIcon />
                                <span>{t('saveToHistory', lang)}</span>
                            </button>
                            <DropdownButton 
                                actions={saveActions} 
                                buttonLabel={t('saveReportButton', lang)}
                                buttonIcon={<SaveReportIcon />}
                            />
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

import type { FormData, CalculationResults, CultureParams, ComplexFertilizer, SpringFertilizer, BasicFertilizerSelections } from '../types';
import { calculateFertigationPlan } from './fertigationCalculator';
import { AMENDMENTS, FERTIGATION_CULTURES, SIMPLE_FERTILIZERS, AMENDMENT_EFFECTS, CULTURES } from '../constants';
import { Language, t, TranslationKey } from '../i18n';

declare const XLSX: any;

export interface ReportData {
    formData: FormData;
    results: CalculationResults;
    calculationType: 'basic' | 'fertigation' | 'full';
    cultureParams: CultureParams;
    springFertilizer: SpringFertilizer;
    nitrogenFertilizer: string;
    complexFertilizer: ComplexFertilizer;
    basicFertilizers: BasicFertilizerSelections;
    selectedAmendment: string;
    springFertilizerRate: number | null;
    lang: Language;
}

const getWeekDateRangeText = (sowingDateStr: string, week: number): string => {
    const sowingDate = sowingDateStr ? new Date(sowingDateStr) : new Date();
    const startDate = new Date(sowingDate);
    startDate.setDate(startDate.getDate() + (week - 1) * 7);
    const endDate = new Date(startDate);
    endDate.setDate(endDate.getDate() + 6);
    return `${startDate.toLocaleDateString('default', { day: '2-digit', month: '2-digit' })}-${endDate.toLocaleDateString('default', { day: '2-digit', month: '2-digit' })}`;
}

const getIdentifiedComplexName = (n: string, p: string, k: string, ca: string, mg: string, lang: Language): string | null => {
    const clear = (val: string) => Math.round(parseFloat(val || '0')).toString();
    const [cN, cP, cK] = [clear(n), clear(p), clear(k)];
    if (cN === '16' && cP === '16' && cK === '16') return t('nitroammophoskaButton', lang);
    if (cN === '2' && cP === '2' && cK === '1') return t('chickenManureButton', lang);
    if (cN === '11' && cP === '11' && cK === '21') return t('yaraMilaButton', lang);
    if (cN === '12' && cP === '12' && cK === '17') return t('rosafertButton', lang);
    if (cN === '9' && cP === '25' && cK === '25') return t('diammophoskaButton', lang);
    return null;
};

const getNormalizedFertName = (n: string, p: string, k: string, ca: string, mg: string, defaultType: string, lang: Language): string => {
    const numN = Math.round(parseFloat(n || '0'));
    const numP = Math.round(parseFloat(p || '0'));
    const numK = Math.round(parseFloat(k || '0'));
    const idName = getIdentifiedComplexName(n, p, k, ca, mg, lang);
    const comp = `N${numN}-P${numP}-K${numK}`;
    return idName ? `${idName} (${comp})` : `${defaultType} ${comp}`;
};

const addCorporateHeader = (aoa: any[][], title: string) => {
    aoa.push(["HARVEST CONSULTING - АГРОХІМІЧНИЙ СЕРВІС"]);
    aoa.push(["Експертні розрахунки систем живлення"]);
    aoa.push(["Контакти: lashyn.aleksandr@gmail.com | +38 (068) 556-84-49"]);
    aoa.push([]); 
    aoa.push([title.toUpperCase()]);
    aoa.push([]); 
};

const getMergesForHeader = (startRow: number) => [
    { s: { r: startRow, c: 0 }, e: { r: startRow, c: 7 } },
    { s: { r: startRow + 1, c: 0 }, e: { r: startRow + 1, c: 7 } },
    { s: { r: startRow + 2, c: 0 }, e: { r: startRow + 2, c: 7 } },
    { s: { r: startRow + 4, c: 0 }, e: { r: startRow + 4, c: 7 } }
];

export const generateTxtReport = (data: ReportData): string => {
    const { formData, results, calculationType, complexFertilizer, lang } = data;
    const cultureName = CULTURES.find(c => c.key === formData.culture)?.name[lang] || formData.culture;
    let report = `==================================================\n   HarvestConsulting\n==================================================\n\n   ${t('resultsTitle', lang, { cultureName })}\n\n`;
    if (calculationType !== 'fertigation') {
        report += `---------- ${t('basicApplicationSection', lang)} ----------\n`;
        if (complexFertilizer?.enabled && parseFloat(complexFertilizer.rate) > 0) {
            report += `${getNormalizedFertName(complexFertilizer.n, complexFertilizer.p2o5, complexFertilizer.k2o, complexFertilizer.cao, complexFertilizer.mg, t('complexFertilizer', lang), lang)}: ${complexFertilizer.rate} kg/ha\n`;
        }
    }
    return report;
};

const addValueToProcurement = (procurement: Record<string, number>, key: string, value: number) => {
    if (!key || isNaN(value) || value <= 0) return;
    const normKey = key.trim();
    procurement[normKey] = (procurement[normKey] || 0) + value;
};

const generateSummarySheet = (reports: ReportData[], lang: Language) => {
    const preSeasonTotals: Record<string, number> = {};
    const monthlyTotals: Record<string, Record<string, number>> = {};

    reports.forEach(report => {
        const { formData, results, cultureParams, springFertilizer, nitrogenFertilizer, complexFertilizer, basicFertilizers, selectedAmendment, springFertilizerRate } = report;
        const area = parseFloat(formData.fieldArea) || 1;

        if (complexFertilizer?.enabled && parseFloat(complexFertilizer.rate) > 0) {
            addValueToProcurement(preSeasonTotals, getNormalizedFertName(complexFertilizer.n, complexFertilizer.p2o5, complexFertilizer.k2o, complexFertilizer.cao, complexFertilizer.mg, t('complexFertilizer', lang), lang), parseFloat(complexFertilizer.rate) * area);
        }
        if (springFertilizer?.enabled && springFertilizerRate && springFertilizerRate > 0) {
            addValueToProcurement(preSeasonTotals, getNormalizedFertName(springFertilizer.n, springFertilizer.p, springFertilizer.k, springFertilizer.ca, springFertilizer.mg, t('springFertilizer', lang), lang), springFertilizerRate * area);
        }

        let basicNeeds = [...results.basic];

        if (selectedAmendment && parseFloat(formData.ph) <= 6.8) {
            const phVal = parseFloat(formData.ph);
            const amendmentRateTons = Math.round((7 - phVal) * 5);
            addValueToProcurement(preSeasonTotals, AMENDMENTS.find(a => a.value === selectedAmendment)?.label[lang] || selectedAmendment, amendmentRateTons * 1000 * area);
            const effect = AMENDMENT_EFFECTS[selectedAmendment as keyof typeof AMENDMENT_EFFECTS];
            if (effect) {
                const caSupplied = effect.calcium * amendmentRateTons;
                const mgSupplied = effect.magnesium * amendmentRateTons;
                basicNeeds = basicNeeds.map(n => {
                    if (n.element === 'CaO') return { ...n, norm: Math.max(0, n.norm - caSupplied) };
                    if (n.element === 'MgO') return { ...n, norm: Math.max(0, n.norm - mgSupplied) };
                    return n;
                });
            }
        }

        if (complexFertilizer?.enabled && parseFloat(complexFertilizer.rate) > 0) {
            const r = parseFloat(complexFertilizer.rate);
            const sup = { 
                'P2O5': r * (parseFloat(complexFertilizer.p2o5||'0')/100), 
                'K2O': r * (parseFloat(complexFertilizer.k2o||'0')/100), 
                'CaO': r * (parseFloat(complexFertilizer.cao||'0')/100), 
                'MgO': r * (parseFloat(complexFertilizer.mg||'0')/100) 
            };
            basicNeeds = basicNeeds.map(n => ({ ...n, norm: Math.max(0, n.norm - (sup[n.element as keyof typeof sup] || 0)) }));
        }

        Object.keys(basicFertilizers).forEach(el => {
            const fert = SIMPLE_FERTILIZERS[el]?.find(f => f.value.toString() === basicFertilizers[el]?.selectedFertilizer);
            const n = basicNeeds.find(n => n.element === el)?.norm || 0;
            if (fert && n > 0) addValueToProcurement(preSeasonTotals, fert.label[lang], (n / fert.value) * 100 * area);
        });

        const cKey = Object.keys(FERTIGATION_CULTURES).find(k => FERTIGATION_CULTURES[k].startsWith(results.culture));
        if (cKey) {
            const { weeklyPlan } = calculateFertigationPlan({ initialNeeds: results.fertigation, cultureKey: cKey, cultureParams, springFertilizer, nitrogenFertilizer, manualRate: springFertilizerRate });
            const fNames = [nitrogenFertilizer === 'urea' ? t('urea', lang) : t('ammoniumNitrate', lang), t('phosphoricAcid', lang), t('potassiumSulfate', lang), t('calciumNitrate', lang), t('magnesiumSulfate', lang)];
            const baseDate = formData.sowingDate ? new Date(formData.sowingDate) : new Date();
            weeklyPlan.forEach(w => {
                const m = t(`month_${new Date(baseDate.getTime() + (w.week-1)*7*24*60*60*1000).getMonth()}` as TranslationKey, lang);
                [w.nitrogen, w.phosphorus, w.potassium, w.calcium, w.magnesium].forEach((v, i) => {
                    if (v > 0) {
                        if (!monthlyTotals[fNames[i]]) monthlyTotals[fNames[i]] = {};
                        monthlyTotals[fNames[i]][m] = (monthlyTotals[fNames[i]][m] || 0) + v * area;
                    }
                });
            });
        }
    });

    const preData = Object.entries(preSeasonTotals).map(([name, totalVal]) => ({ 
        [t('fertilizerNameHeader', lang)]: name, 
        [t('totalNeededKgHeader', lang)]: parseFloat(totalVal.toFixed(1)),
        "Unit": "kg"
    }));

    const months = [...new Set(Object.values(monthlyTotals).flatMap(m => Object.keys(m)))].sort((a,b) => {
        const o = Array.from({length:12}, (_,i)=>t(`month_${i}` as TranslationKey, lang));
        return o.indexOf(a) - o.indexOf(b);
    });

    const monData = Object.keys(monthlyTotals).sort().map(f => {
        const row: any = { [t('fertilizerNameHeader', lang)]: f };
        let s = 0;
        months.forEach(m => { 
            const v = monthlyTotals[f][m] || 0; 
            row[m] = v > 0 ? parseFloat(v.toFixed(1)) : ''; 
            s += v; 
        });
        row[t('totalLabel', lang)] = parseFloat(s.toFixed(1));
        row["Unit"] = "kg";
        return row;
    });

    let aoa: any[][] = [];
    addCorporateHeader(aoa, t('summarySheet', lang));

    const ws = XLSX.utils.aoa_to_sheet(aoa);

    // Add sections with visual padding
    let currentLastRow = aoa.length;
    XLSX.utils.sheet_add_aoa(ws, [[t('preSeasonFertilizersHeader', lang).toUpperCase()]], { origin: `A${currentLastRow + 1}` });
    XLSX.utils.sheet_add_json(ws, preData, { origin: `A${currentLastRow + 2}`, skipHeader: false });

    currentLastRow += preData.length + 5;
    XLSX.utils.sheet_add_aoa(ws, [[t('monthlyNeedsHeader', lang).toUpperCase()]], { origin: `A${currentLastRow}` });
    XLSX.utils.sheet_add_json(ws, monData, { origin: `A${currentLastRow + 1}`, skipHeader: false });

    ws['!cols'] = [{ wch: 50 }, ...months.map(() => ({ wch: 12 })), { wch: 15 }, { wch: 8 }];
    ws['!merges'] = getMergesForHeader(0);
    return ws;
};

const generateDetailsSheet = (reports: ReportData[], lang: Language) => {
    let aoa: any[][] = [];
    addCorporateHeader(aoa, t('detailsSheet', lang));

    reports.forEach((report, idx) => {
        const { formData, results, cultureParams, springFertilizer, nitrogenFertilizer, complexFertilizer, basicFertilizers, selectedAmendment, springFertilizerRate } = report;
        const area = parseFloat(formData.fieldArea) || 1;
        const cultureName = CULTURES.find(c => c.key === formData.culture)?.name[lang] || formData.culture;

        if (idx > 0) { aoa.push([], [], ["================================================================================================="], []); }

        aoa.push([`ОБ'ЄКТ: ${formData.fieldName || 'Поле ' + (idx+1)}`]);
        aoa.push([`${t('cultureLabel', lang)}: ${cultureName}`, `${t('fieldAreaLabel', lang)}: ${area} ha`, `${t('plannedYieldLabel', lang)}: ${formData.plannedYield} t/ha`]);
        aoa.push([`Аналіз ґрунту: pH=${formData.ph}, ЄКО=${formData.cec}, N=${formData.nitrogenAnalysis}, P2O5=${formData.phosphorus}, K2O=${formData.potassium}, CaO=${formData.calcium}, MgO=${formData.magnesium}`]);

        if (report.calculationType !== 'fertigation') {
            aoa.push([], [t('basicApplicationSection', lang).toUpperCase()], [t('fertilizerTypeHeader', lang), t('fertilizerNameCompositionHeader', lang), `${t('applicationRate', lang)} (kg/ha)`, `${t('totalLabel', lang)} (kg)`]);

            let needs = [...results.basic];

            if (selectedAmendment && parseFloat(formData.ph) <= 6.8) {
                const phVal = parseFloat(formData.ph);
                const r = Math.round((7 - phVal) * 5) * 1000;
                aoa.push([t('amendmentLabel', lang), AMENDMENTS.find(a => a.value === selectedAmendment)?.label[lang] || selectedAmendment, r, r * area]);
                const effect = AMENDMENT_EFFECTS[selectedAmendment as keyof typeof AMENDMENT_EFFECTS];
                if (effect) {
                    needs = needs.map(n => {
                        if (n.element === 'CaO') return { ...n, norm: Math.max(0, n.norm - effect.calcium * Math.round((7 - phVal) * 5)) };
                        if (n.element === 'MgO') return { ...n, norm: Math.max(0, n.norm - effect.magnesium * Math.round((7 - phVal) * 5)) };
                        return n;
                    });
                }
            }

            if (complexFertilizer?.enabled && parseFloat(complexFertilizer.rate) > 0) {
                const n = getNormalizedFertName(complexFertilizer.n, complexFertilizer.p2o5, complexFertilizer.k2o, complexFertilizer.cao, complexFertilizer.mg, t('complexFertilizer', lang), lang);
                const r = parseFloat(complexFertilizer.rate);
                aoa.push([t('complexFertilizer', lang), n, r, r * area]);
                const sup = { 
                    'P2O5': r * (parseFloat(complexFertilizer.p2o5||'0')/100), 
                    'K2O': r * (parseFloat(complexFertilizer.k2o||'0')/100), 
                    'CaO': r * (parseFloat(complexFertilizer.cao||'0')/100), 
                    'MgO': r * (parseFloat(complexFertilizer.mg||'0')/100) 
                };
                needs = needs.map(n => ({ ...n, norm: Math.max(0, n.norm - (sup[n.element as keyof typeof sup] || 0)) }));
            }

            needs.filter(n => n.element !== 'Меліорант' && n.norm > 0).forEach(n => {
                const f = SIMPLE_FERTILIZERS[n.element]?.find(f => f.value.toString() === basicFertilizers[n.element]?.selectedFertilizer);
                if (f) {
                    const r = (n.norm / f.value) * 100;
                    aoa.push([`${t('fertilizerLabel', lang)} (${n.element})`, f.label[lang], parseFloat(r.toFixed(1)), parseFloat((r * area).toFixed(1))]);
                }
            });
        }

        if (report.calculationType !== 'basic') {
            aoa.push([], [t('fertigationProgramSection', lang).toUpperCase()]);
            if (springFertilizer?.enabled && springFertilizerRate && springFertilizerRate > 0) {
                const n = getNormalizedFertName(springFertilizer.n, springFertilizer.p, springFertilizer.k, springFertilizer.ca, springFertilizer.mg, t('springFertilizer', lang), lang);
                aoa.push([t('springFertilizer', lang), n, springFertilizerRate, springFertilizerRate * area]);
            }
            const cK = Object.keys(FERTIGATION_CULTURES).find(k => FERTIGATION_CULTURES[k].startsWith(results.culture));
            if (cK) {
                const { weeklyPlan, totals } = calculateFertigationPlan({ initialNeeds: results.fertigation, cultureKey: cK, cultureParams, springFertilizer, nitrogenFertilizer, manualRate: springFertilizerRate });
                const fNs = [nitrogenFertilizer === 'urea' ? t('urea', lang) : t('ammoniumNitrate', lang), t('phosphoricAcid', lang), t('potassiumSulfate', lang), t('calciumNitrate', lang), t('magnesiumSulfate', lang)];

                aoa.push([], [t('week', lang), t('dateRangeHeader', lang), ...fNs.map(n => `${n} (kg/ha)`)]);
                weeklyPlan.forEach(w => {
                    const row = [w.week, getWeekDateRangeText(formData.sowingDate, w.week)];
                    [w.nitrogen, w.phosphorus, w.potassium, w.calcium, w.magnesium].forEach(v => row.push(v > 0 ? parseFloat(v.toFixed(1)) : ''));
                    aoa.push(row);
                });
                aoa.push([t('totalLabel', lang), '', parseFloat(totals.nitrogen.toFixed(1)), parseFloat(totals.phosphorus.toFixed(1)), parseFloat(totals.potassium.toFixed(1)), parseFloat(totals.calcium.toFixed(1)), parseFloat(totals.magnesium.toFixed(1))]);
            }
        }
    });

    const ws = XLSX.utils.aoa_to_sheet(aoa);
    ws['!cols'] = [{ wch: 30 }, { wch: 45 }, { wch: 15 }, { wch: 15 }, { wch: 15 }, { wch: 15 }, { wch: 15 }, { wch: 15 }];
    ws['!merges'] = getMergesForHeader(0);
    return ws;
};

export const generateXlsxReport = (reports: ReportData[], lang: Language) => {
    try {
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, generateSummarySheet(reports, lang), t('summarySheet', lang));
        XLSX.utils.book_append_sheet(wb, generateDetailsSheet(reports, lang), t('detailsSheet', lang));
        XLSX.writeFile(wb, "HarvestConsulting_Fertilizer_Plan.xlsx");
    } catch (e) { console.error(e); alert("XLSX error"); }
};

import React from 'react';
import type { FormData } from '../types';
import { StyledFormField } from './StyledFormField';
import { DropdownButton, DropdownAction } from './SaveButtonDropdown';
import { Language, t } from '../i18n';

interface Step1Props {
    onNext: () => void;
    onBack: () => void;
    data: FormData;
    onDataChange: (newData: Partial<FormData>) => void;
    lang: Language;
}

const DataActionsIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m12 0a2 2 0 100-4m0 4a2 2 0 110-4m-6 0a2 2 0 100-4m0 4a2 2 0 110-4" />
        <path strokeLinecap="round" strokeLinejoin="round" d="M12 18a2 2 0 100-4m0 4a2 2 0 110-4" />
    </svg>
);

export const Step1SoilAnalysis: React.FC<Step1Props> = ({ onNext, onBack, data, onDataChange, lang }) => {
    const LOCAL_STORAGE_KEY = 'savedSoilAnalysisData';

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, value } = e.target;
        onDataChange({ [name]: value });
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        onNext();
    };

    const handleSaveData = () => {
        try {
            const dataToSave = {
                nitrogenAnalysis: data.nitrogenAnalysis,
                phosphorus: data.phosphorus,
                potassium: data.potassium,
                calcium: data.calcium,
                magnesium: data.magnesium,
                ph: data.ph,
                cec: data.cec,
            };
            localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(dataToSave));
            alert(t('dataSavedSuccess', lang));
        } catch (error) {
            console.error("Failed to save soil analysis data to localStorage", error);
            alert(t('dataSaveError', lang));
        }
    };

    const handleLoadData = () => {
        try {
            const savedData = localStorage.getItem(LOCAL_STORAGE_KEY);
            if (savedData) {
                const parsedData = JSON.parse(savedData);
                if (parsedData && typeof parsedData === 'object' && !Array.isArray(parsedData)) {
                    onDataChange(parsedData);
                    alert(t('dataLoadedSuccess', lang));
                } else {
                     console.warn('Stored soil analysis data is not a valid object, removing.');
                     localStorage.removeItem(LOCAL_STORAGE_KEY);
                     alert(t('dataLoadInvalid', lang));
                }
            } else {
                alert(t('dataNotFound', lang));
            }
        } catch (error) {
            console.error("Failed to load saved soil analysis data from localStorage", error);
            alert(t('dataLoadError', lang));
            localStorage.removeItem(LOCAL_STORAGE_KEY);
        }
    };

    const cecTooltip = t('cecTooltip', lang);

    const dataActions: DropdownAction[] = [
        {
            label: t('saveDataAction', lang),
            onClick: handleSaveData,
            iconType: 'save'
        },
        {
            label: t('loadDataAction', lang),
            onClick: handleLoadData,
            iconType: 'upload'
        }
    ];

    return (
        <form onSubmit={handleSubmit} className="space-y-8">
            <h2 className="text-2xl font-semibold text-slate-800 border-b pb-4 mb-6">{t('step1Title', lang)}</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <StyledFormField label={t('nitrogenAnalysisLabel', lang)} name="nitrogenAnalysis" value={data.nitrogenAnalysis} onChange={handleChange} unit="mg/kg" />
                <StyledFormField label={t('phosphorusLabel', lang)} name="phosphorus" value={data.phosphorus} onChange={handleChange} unit="mg/kg" />
                <StyledFormField label={t('potassiumLabel', lang)} name="potassium" value={data.potassium} onChange={handleChange} unit="mg/kg" />
                <StyledFormField label={t('calciumLabel', lang)} name="calcium" value={data.calcium} onChange={handleChange} unit="mg/kg" />
                <StyledFormField label={t('magnesiumLabel', lang)} name="magnesium" value={data.magnesium} onChange={handleChange} unit="mg/kg" />
                <StyledFormField label={t('phLabel', lang)} name="ph" value={data.ph} onChange={handleChange} unit="" step="0.1" max="14" />
                <StyledFormField 
                    label={t('cecLabel', lang)}
                    name="cec" 
                    value={data.cec} 
                    onChange={handleChange} 
                    unit="mg-eq/100g"
                    tooltipText={cecTooltip}
                />
            </div>

             <div className="flex flex-col sm:flex-row justify-between items-center gap-4 pt-8 border-t mt-8">
                <div className="flex flex-wrap items-center gap-4 w-full sm:w-auto">
                     <button
                        type="button"
                        onClick={onBack}
                        className="bg-slate-300 text-slate-800 font-bold py-3 px-6 rounded-lg hover:bg-slate-400 transition duration-300 w-full sm:w-auto"
                    >
                        {t('backButton', lang)}
                    </button>
                    <DropdownButton actions={dataActions} buttonLabel={t('dataActionsButton', lang)} buttonIcon={<DataActionsIcon />} />
                </div>
                <button
                    type="submit"
                    className="w-full sm:w-auto bg-indigo-600 text-white font-bold py-3 px-10 rounded-lg hover:bg-indigo-700 transition duration-300 shadow-lg text-lg"
                >
                    {t('nextButton', lang)}
                </button>
            </div>
        </form>
    );
};

