import React, { useMemo, useEffect } from 'react';
import type { FormData, NutrientNeeds, BasicFertilizerSelections, ComplexFertilizer } from '../types';
import { SIMPLE_FERTILIZERS, AMENDMENTS, AMENDMENT_EFFECTS } from '../constants';
import { StyledFormField } from './StyledFormField';
import { Tooltip } from './Tooltip';
import { InfoIcon } from './InfoIcon';
import { Language, t } from '../i18n';

interface BasicApplicationCalculatorProps {
    needs: NutrientNeeds[];
    formData: Partial<FormData>;
    selections: BasicFertilizerSelections;
    onSelectionsChange: (selections: BasicFertilizerSelections) => void;
    amendment: string;
    onAmendmentChange: (amendment: string) => void;
    complexFertilizer: ComplexFertilizer;
    onComplexFertilizerChange: (fertilizer: ComplexFertilizer) => void;
    readOnly?: boolean;
    lang: Language;
}

const DEFAULT_FERTILIZERS: Record<string, string> = {
    'P2O5': '19', // Суперфосфат
    'K2O': '60',  // Калій хлористий
    'CaO': '35',  // Сульфат кальцію (гіпс)
    'MgO': '16',  // Сульфат магнію
};

const ComplexFertilizerInput: React.FC<{ label: string, name: keyof Omit<ComplexFertilizer, 'rate' | 'enabled'>, value: string, onChange: (e: React.ChangeEvent<HTMLInputElement>) => void, disabled?: boolean }> = ({ label, name, value, onChange, disabled }) => (
    <div>
        <label htmlFor={`complex-${name}`} className="block text-sm font-medium text-slate-700 text-center" dangerouslySetInnerHTML={{ __html: label }} />
        <div className="mt-1 relative rounded-md shadow-sm">
            <input
                type="number"
                name={name}
                id={`complex-${name}`}
                value={value}
                onChange={onChange}
                className="w-full pl-2 pr-6 py-1.5 border border-slate-300 rounded-md text-center focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 disabled:bg-slate-100"
                placeholder="0"
                min="0"
                max="100"
                step="0.1"
                disabled={disabled}
                aria-label={`Відсоток ${label}`}
            />
            <div className="absolute inset-y-0 right-0 pr-2 flex items-center pointer-events-none">
                <span className="text-slate-500 sm:text-sm">%</span>
            </div>
        </div>
    </div>
);


export const BasicApplicationCalculator: React.FC<BasicApplicationCalculatorProps> = ({
    needs,
    formData,
    selections,
    onSelectionsChange,
    amendment,
    onAmendmentChange,
    complexFertilizer,
    onComplexFertilizerChange,
    readOnly = false,
    lang
}) => {

    useEffect(() => {
        if (!readOnly) {
            const initialSelections: BasicFertilizerSelections = {};
            needs.forEach(need => {
                if (need.norm > 0 && DEFAULT_FERTILIZERS[need.element] && !selections[need.element]) {
                    initialSelections[need.element] = {
                        selectedFertilizer: DEFAULT_FERTILIZERS[need.element],
                    };
                }
            });
            if (Object.keys(initialSelections).length > 0) {
                onSelectionsChange({ ...selections, ...initialSelections });
            }
        }
    }, [needs, readOnly]);

    const fieldArea = parseFloat(formData.fieldArea || '1') || 1;
    const ph = formData.ph;
    const needsAmendment = ph && parseFloat(ph) <= 6.8;

    const displayNeeds = useMemo<NutrientNeeds[]>(() => {
        if (!amendment || !needsAmendment || !formData.ph) {
            return needs.map(need => need.element === 'Меліорант' ? { ...need, norm: 0 } : need);
        }
        const amendmentEffects = AMENDMENT_EFFECTS[amendment as keyof typeof AMENDMENT_EFFECTS];
        const numericPh = parseFloat(formData.ph);
        const initialCaNeed = needs.find(n => n.element === 'CaO')?.norm ?? 0;
        const initialMgNeed = needs.find(n => n.element === 'MgO')?.norm ?? 0;
        const amendmentRateTons = Math.round((7 - numericPh) * 5);
        const amendmentRateKg = amendmentRateTons * 1000;
        const calciumFromAmendment = amendmentEffects.calcium * amendmentRateTons;
        const magnesiumFromAmendment = amendmentEffects.magnesium * amendmentRateTons;
        const newCalciumRate = Math.round(Math.max(0, initialCaNeed - calciumFromAmendment));
        const newMagnesiumRate = Math.round(Math.max(0, initialMgNeed - magnesiumFromAmendment));
        return needs.map(need => {
            if (need.element === 'Меліорант') return { ...need, norm: amendmentRateKg };
            if (need.element === 'CaO') return { ...need, norm: newCalciumRate };
            if (need.element === 'MgO') return { ...need, norm: newMagnesiumRate };
            return need;
        });
    }, [needs, amendment, needsAmendment, formData.ph]);

    // Check if there are any nutrient needs (except amendment) to decide whether to show complex fertilizer option
    const hasNutrientNeeds = useMemo(() => {
        return needs.some(n => n.element !== 'Меліорант' && n.norm > 0);
    }, [needs]);

    useEffect(() => {
        if (!complexFertilizer.enabled) return;
        const complexContent = {
            'P2O5': parseFloat(complexFertilizer.p2o5 || '0'),
            'K2O': parseFloat(complexFertilizer.k2o || '0'),
            'CaO': parseFloat(complexFertilizer.cao || '0'),
            'MgO': parseFloat(complexFertilizer.mg || '0'),
        };
        let maxRate = 0;
        displayNeeds.forEach(need => {
            const percentage = complexContent[need.element as keyof typeof complexContent];
            if (need.norm > 0 && percentage > 0) {
                const requiredRate = (need.norm / percentage) * 100;
                if (requiredRate > maxRate) maxRate = requiredRate;
            }
        });
        const newRate = maxRate > 0 ? Math.round(maxRate).toString() : '';
        if (newRate !== complexFertilizer.rate) {
            onComplexFertilizerChange({ ...complexFertilizer, rate: newRate });
        }
    }, [complexFertilizer.enabled, complexFertilizer.p2o5, complexFertilizer.k2o, complexFertilizer.cao, complexFertilizer.mg, displayNeeds]);

    const handleToggleComplexFertilizer = (e: React.ChangeEvent<HTMLInputElement>) => {
        const isEnabled = e.target.checked;
        if (isEnabled) {
            onComplexFertilizerChange({ ...complexFertilizer, enabled: true });
        } else {
            onComplexFertilizerChange({ n: '', p2o5: '', k2o: '', cao: '', mg: '', rate: '', enabled: false });
        }
    };

    const handleComplexFertilizerInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, value } = e.target;
        onComplexFertilizerChange({ ...complexFertilizer, [name]: value });
    };

    const handleNitroammophoskaClick = () => {
        onComplexFertilizerChange({
            ...complexFertilizer,
            n: '16', p2o5: '16', k2o: '16', cao: '', mg: '',
            enabled: true,
        });
    };

    const handleChickenManureClick = () => {
        onComplexFertilizerChange({
            ...complexFertilizer,
            n: '2', p2o5: '2', k2o: '1', cao: '2.4', mg: '0.2',
            enabled: true,
        });
    };

    const handleDiammophoskaClick = () => {
        onComplexFertilizerChange({
            ...complexFertilizer,
            n: '9', p2o5: '25', k2o: '25', cao: '', mg: '',
            enabled: true,
        });
    };

    const finalNeeds = useMemo(() => {
        const rate = parseFloat(complexFertilizer.rate);
        if (!complexFertilizer.enabled || !rate || isNaN(rate) || rate <= 0) return displayNeeds;
        const supplied = {
            'P2O5': rate * (parseFloat(complexFertilizer.p2o5 || '0') / 100),
            'K2O': rate * (parseFloat(complexFertilizer.k2o || '0') / 100),
            'CaO': rate * (parseFloat(complexFertilizer.cao || '0') / 100),
            'MgO': rate * (parseFloat(complexFertilizer.mg || '0') / 100),
        };
        return displayNeeds.map(need => {
            if (need.element === 'Меліорант') return need;
            const suppliedAmount = supplied[need.element as keyof typeof supplied] || 0;
            return { ...need, norm: Math.round(Math.max(0, need.norm - suppliedAmount)) };
        });
    }, [displayNeeds, complexFertilizer]);

    const handleAmendmentChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
        onAmendmentChange(e.target.value);
    };

    const handleFertilizerChange = (element: string, fertilizerValue: string) => {
        onSelectionsChange({ ...selections, [element]: { selectedFertilizer: fertilizerValue } });
    };

    const getCalculatedNorm = (element: string, nutrientNorm: number) => {
        const selection = selections[element];
        if (!selection || !selection.selectedFertilizer) return 0;
        const percentage = parseFloat(selection.selectedFertilizer);
        if (isNaN(percentage) || percentage === 0 || nutrientNorm === 0) return 0;
        return Math.round((nutrientNorm / percentage) * 100);
    };

    const nutrientNeeds = finalNeeds.filter(need => need.element !== 'Меліорант' && need.norm > 0);
    const complexFertilizerTotal = (parseFloat(complexFertilizer.rate) || 0) * fieldArea;

    return (
        <div>
            <h3 className="text-xl font-semibold mb-4 text-slate-700 border-b pb-2">{t('basicApplicationHeader', lang)}</h3>

            {/* Always show the complex fertilizer option if there is any nutrient need */}
            {hasNutrientNeeds && (
                 <div className="mb-6 p-4 border border-indigo-200 rounded-lg bg-indigo-50">
                    <div className="relative flex items-start">
                        <div className="flex h-6 items-center">
                            <input id="complex-toggle" type="checkbox" checked={complexFertilizer.enabled} onChange={handleToggleComplexFertilizer} className="h-4 w-4 rounded border-slate-300 text-indigo-600 focus:ring-indigo-600" disabled={readOnly} />
                        </div>
                        <div className="ml-3 text-sm leading-6">
                            <label htmlFor="complex-toggle" className="font-medium text-slate-900 cursor-pointer">{t('addComplexFertilizer', lang)}</label>
                            <p className="text-slate-500">{t('addComplexFertilizerDesc', lang)}</p>
                        </div>
                    </div>
                 </div>
            )}

            {complexFertilizer.enabled && (
                <div className="mb-8 p-4 border rounded-lg bg-slate-50 space-y-4 shadow-inner">
                    <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-2">
                        <h4 className="text-lg font-semibold text-slate-800">{t('complexFertilizerHeader', lang)}</h4>
                        {!readOnly && (
                            <div className="flex flex-wrap gap-2">
                                <button type="button" onClick={handleNitroammophoskaClick} className="bg-indigo-100 text-indigo-700 text-xs font-semibold px-4 py-1.5 rounded-full hover:bg-indigo-200 transition-colors shadow-sm">{t('nitroammophoskaButton', lang)}</button>
                                <button type="button" onClick={handleChickenManureClick} className="bg-amber-100 text-amber-700 text-xs font-semibold px-4 py-1.5 rounded-full hover:bg-amber-200 transition-colors shadow-sm">{t('chickenManureButton', lang)}</button>
                                <button type="button" onClick={handleDiammophoskaClick} className="bg-orange-100 text-orange-700 text-xs font-semibold px-4 py-1.5 rounded-full hover:bg-orange-200 transition-colors shadow-sm">{t('diammophoskaButton', lang)}</button>
                            </div>
                        )}
                    </div>
                    <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-4">
                       <ComplexFertilizerInput label="N" name="n" value={complexFertilizer.n} onChange={handleComplexFertilizerInputChange} disabled={readOnly} />
                       <ComplexFertilizerInput label="P₂O₅" name="p2o5" value={complexFertilizer.p2o5} onChange={handleComplexFertilizerInputChange} disabled={readOnly} />
                       <ComplexFertilizerInput label="K₂O" name="k2o" value={complexFertilizer.k2o} onChange={handleComplexFertilizerInputChange} disabled={readOnly} />
                       <ComplexFertilizerInput label="CaO" name="cao" value={complexFertilizer.cao} onChange={handleComplexFertilizerInputChange} disabled={readOnly} />
                       <ComplexFertilizerInput label="MgO" name="mg" value={complexFertilizer.mg} onChange={handleComplexFertilizerInputChange} disabled={readOnly} />
                    </div>
                     <div className="pt-2">
                        <StyledFormField label={t('complexFertilizerRateLabel', lang)} name="rate" value={complexFertilizer.rate} onChange={() => {}} unit="kg/ha" disabled={true} />
                        {complexFertilizerTotal > 0 && <p className="text-sm text-slate-600 mt-1 text-right font-medium">{t('totalForArea', lang)} <span className="font-bold text-indigo-700">{complexFertilizerTotal.toFixed(1)} kg</span></p>}
                    </div>
                </div>
            )}
            <div className="overflow-x-auto rounded-lg shadow-md border border-slate-200">
                <table className="min-w-full bg-white">
                    <thead className="bg-slate-100">
                        <tr>
                            <th className="py-3 px-6 text-left text-sm font-semibold uppercase text-slate-600">{t('element', lang)}</th>
                            <th className="py-3 px-6 text-left text-sm font-semibold uppercase text-slate-600">{complexFertilizer.enabled ? t('remainingNeed', lang) : t('need', lang)}</th>
                            <th className="py-3 px-6 text-left text-sm font-semibold uppercase text-slate-600">{t('fertilizerLabel', lang)}</th>
                            <th className="py-3 px-6 text-left text-sm font-semibold uppercase text-slate-600">{t('applicationRate', lang)}</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-200">
                        {nutrientNeeds.map(need => {
                            const calculatedNorm = getCalculatedNorm(need.element, need.norm);
                            return (
                                <tr key={need.element} className="hover:bg-indigo-50">
                                    <td className="py-4 px-6 whitespace-nowrap font-medium text-slate-800">{need.element}</td>
                                    <td className="py-4 px-6 whitespace-nowrap text-slate-700">{need.norm} kg/ha</td>
                                    <td className="py-4 px-6 whitespace-nowrap">
                                        <select value={selections[need.element]?.selectedFertilizer || ''} onChange={(e) => handleFertilizerChange(need.element, e.target.value)} className="w-full px-3 py-1.5 border border-slate-300 rounded-md text-sm disabled:bg-slate-100" disabled={readOnly}>
                                            <option value=""></option>
                                            {(SIMPLE_FERTILIZERS[need.element] || []).map(fert => <option key={fert.value} value={fert.value}>{fert.label[lang]} ({fert.value}%)</option>)}
                                        </select>
                                    </td>
                                    <td className="py-4 px-6 whitespace-nowrap font-semibold text-indigo-600">
                                        {calculatedNorm > 0 && <div><p>{calculatedNorm} kg/ha</p><p className="text-xs text-slate-600">({(calculatedNorm * fieldArea).toFixed(1)} kg)</p></div>}
                                    </td>
                                </tr>
                            );
                        })}
                        {needsAmendment && (
                             <tr className="bg-indigo-50/70">
                                <td className="py-4 px-6 whitespace-nowrap font-medium text-slate-800 flex items-center gap-1.5">{t('amendmentLabel', lang)} <Tooltip text={t('amendmentTooltip', lang)}><InfoIcon className="h-4 w-4" /></Tooltip></td>
                                <td className="py-4 px-6 whitespace-nowrap font-bold text-slate-700">{Math.round((7 - parseFloat(ph)) * 5) * 1000} kg/ha</td>
                                <td className="py-4 px-6 whitespace-nowrap">
                                    <select value={amendment} onChange={handleAmendmentChange} className="w-full px-3 py-1.5 border border-slate-300 rounded-md text-sm disabled:bg-slate-100" disabled={readOnly}>
                                        <option value=""></option>
                                        {AMENDMENTS.map(amend => <option key={amend.value} value={amend.value}>{amend.label[lang]}</option>)}
                                    </select>
                                </td>
                                 <td className="py-4 px-6 whitespace-nowrap text-sm text-indigo-600 font-semibold">{amendment && `${(Math.round((7 - parseFloat(ph)) * 5) * 1000 * fieldArea).toFixed(0)} kg`}</td>
                            </tr>
                        )}
                        {nutrientNeeds.length === 0 && !needsAmendment && (
                             <tr>
                                <td colSpan={4} className="py-10 text-center text-slate-500 italic">
                                    {t('basicApplicationNotNeeded', lang)}
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export interface NutrientNeeds {
    element: string;
    norm: number;
}

export interface CalculationResults {
    culture: string;
    basic: NutrientNeeds[];
    fertigation: NutrientNeeds[];
}

export interface CultureParams {
    nitrogenFactor: number;
    potassiumRanges: { min: number; max: number; value: number }[];
    calciumFactor: number;
    magnesiumFactor: number;
}

export interface FormData {
    culture: string;
    plannedYield: string;
    sowingDate: string;
    fieldArea: string;
    fieldName: string;
    nitrogenAnalysis: string;
    ph: string;
    phosphorus: string;
    potassium: string;
    calcium: string;
    magnesium: string;
    cec: string;
    amendment: string;
}

export type BasicFertilizerSelections = {
    [element: string]: {
        selectedFertilizer: string;
    };
};

export interface ComplexFertilizer {
    n: string;
    p2o5: string;
    k2o: string;
    cao: string;
    mg: string;
    rate: string;
    enabled: boolean;
}

export interface SpringFertilizer {
    n: string;
    p: string;
    k: string;
    ca: string;
    mg: string;
    enabled: boolean;
    kCompensation?: number;
}

export interface SavedReport {
  id: string;
  timestamp: string;
  formData: FormData;
  results: CalculationResults;
  calculationType: 'basic' | 'fertigation' | 'full';
  springFertilizer: SpringFertilizer;
  nitrogenFertilizer: string;
  basicFertilizers: BasicFertilizerSelections;
  selectedAmendment: string;
  complexFertilizer?: ComplexFertilizer;
  springFertilizerRate?: number | null;
}

import React, { useState, useEffect, useRef } from 'react';
import type { CalculationResults, FormData, NutrientNeeds, CultureParams, SavedReport, BasicFertilizerSelections, ComplexFertilizer, SpringFertilizer } from './types';
import { Stepper } from './components/Stepper';
import { Step1SoilAnalysis } from './components/Step1SoilAnalysis';
import { Step2CropYield } from './components/Step2CropYield';
import { Step3CalculationChoice } from './components/Step3CalculationChoice';
import { Step4Results } from './components/Step4Results';
import { CULTURE_PARAMS } from './constants';
import { ReportsList } from './components/ReportsList';
import { ReportDetail } from './components/ReportDetail';
import { Logo } from './components/Logo';
import { generateTxtReport, generateXlsxReport } from './utils/reportGenerator';
import { t, Language } from './i18n';
import { SaveConfirmationModal } from './components/SaveConfirmationModal';
import { calculateNutrientNeeds } from './utils/nutrientCalculations';

const createInitialComplexFertilizer = (): ComplexFertilizer => ({
    n: '', p2o5: '', k2o: '', cao: '', mg: '', rate: '', enabled: false
});

const createInitialSpringFertilizer = (): SpringFertilizer => ({
    n: '', p: '', k: '', ca: '', mg: '', enabled: false, kCompensation: 50
});

const createInitialSelections = (): FertilizerSelections => ({
    springFertilizer: createInitialSpringFertilizer(),
    nitrogenFertilizer: 'ammonium-nitrate',
    basicFertilizers: {},
    selectedAmendment: '',
    complexFertilizer: createInitialComplexFertilizer(),
    springFertilizerRate: null,
});

const INITIAL_FORM_DATA: FormData = {
    culture: '',
    plannedYield: '',
    sowingDate: '',
    fieldArea: '1',
    fieldName: '',
    nitrogenAnalysis: '5',
    ph: '7.0',
    phosphorus: '50',
    potassium: '100',
    calcium: '2000',
    magnesium: '100',
    cec: '15',
    amendment: '',
};

interface FertilizerSelections {
  springFertilizer: SpringFertilizer;
  nitrogenFertilizer: string;
  basicFertilizers: BasicFertilizerSelections;
  selectedAmendment: string;
  complexFertilizer: ComplexFertilizer;
  springFertilizerRate: number | null;
}

// Project structure for saving/loading full state
interface AgroProject {
    version: string;
    type: 'project';
    mode: 'single' | 'group';
    analyses: FormData[];
    activeAnalysisIndex: number;
    calculationType: 'basic' | 'fertigation' | 'full' | null;
    selections: FertilizerSelections[]; // Array matching analyses
}

function App() {
    const [mainView, setMainView] = useState<'landing' | 'calculator' | 'reports'>('landing');
    const [analysisMode, setAnalysisMode] = useState<'single' | 'group' | null>(null);
    const [currentStep, setCurrentStep] = useState(1);
    const [analyses, setAnalyses] = useState<FormData[]>([{...INITIAL_FORM_DATA, culture: 'Томат', plannedYield: '100'}]);
    const [activeAnalysisIndex, setActiveAnalysisIndex] = useState(0);

    const [results, setResults] = useState<CalculationResults | null>(null);
    const [groupResults, setGroupResults] = useState<(CalculationResults | null)[]>([]);
    const [calculationType, setCalculationType] = useState<'basic' | 'fertigation' | 'full' | null>(null);

    // Single mode states
    const [springFertilizer, setSpringFertilizer] = useState<SpringFertilizer>(createInitialSpringFertilizer());
    const [nitrogenFertilizer, setNitrogenFertilizer] = useState('ammonium-nitrate');
    const [basicFertilizers, setBasicFertilizers] = useState<BasicFertilizerSelections>({});
    const [selectedAmendment, setSelectedAmendment] = useState('');
    const [complexFertilizer, setComplexFertilizer] = useState<ComplexFertilizer>(createInitialComplexFertilizer());
    const [springFertilizerRate, setSpringFertilizerRate] = useState<number | null>(null);

    // Group mode states
    const [groupFertilizerSelections, setGroupFertilizerSelections] = useState<FertilizerSelections[]>([]);
    const [recordedIndices, setRecordedIndices] = useState<Set<number>>(new Set());
    const [isSaveModalOpen, setIsSaveModalOpen] = useState(false);

    const [language, setLanguage] = useState<Language>(() => {
        const savedLang = localStorage.getItem('agro-calc-lang');
        return (savedLang as Language) || 'uk';
    });

    const [reports, setReports] = useState<SavedReport[]>(() => {
        try {
            const saved = localStorage.getItem('agro-reports');
            if (!saved) return [];
            return JSON.parse(saved);
        } catch (e) {
            return [];
        }
    });
    const [selectedReport, setSelectedReport] = useState<SavedReport | null>(null);
    const [customLogoUrl, setCustomLogoUrl] = useState<string | null>(localStorage.getItem('custom-logo'));
    const fileInputRef = useRef<HTMLInputElement>(null);
    const reportInputRef = useRef<HTMLInputElement>(null);

    const currentFormData = analyses[activeAnalysisIndex] || {...INITIAL_FORM_DATA};

    useEffect(() => {
        localStorage.setItem('agro-reports', JSON.stringify(reports));
    }, [reports]);

    useEffect(() => {
        localStorage.setItem('agro-calc-lang', language);
    }, [language]);

    const updateCurrentAnalysis = (data: Partial<FormData>) => {
        setAnalyses(prev => {
            const newAnalyses = [...prev];
            newAnalyses[activeAnalysisIndex] = { ...newAnalyses[activeAnalysisIndex], ...data };
            return newAnalyses;
        });
    };

    const handleNext = () => setCurrentStep(prev => prev + 1);
    const handleBack = () => setCurrentStep(prev => prev - 1);

    const handleCalculate = () => {
        setResults(calculateNutrientNeeds(currentFormData));
        setGroupResults([]);
        setCurrentStep(3);
    };

    const handleCalculateAll = () => {
        const allResults = analyses.map(f => calculateNutrientNeeds(f));
        setGroupResults(allResults);

        setGroupFertilizerSelections(prev => {
            return analyses.map((_, i) => {
                if (prev[i]) return prev[i];
                return createInitialSelections();
            });
        });

        setRecordedIndices(new Set(analyses.map((_, i) => i)));
        setResults(null);
        setCurrentStep(3);
    };

    const handleSelectCalculation = (type: 'basic' | 'fertigation' | 'full') => {
        setCalculationType(type);
        setCurrentStep(4);
    };

    const handleReset = () => {
        setCurrentStep(1);
        setAnalyses([{ ...INITIAL_FORM_DATA, culture: 'Томат', plannedYield: '100' }]);
        setActiveAnalysisIndex(0);
        setResults(null);
        setGroupResults([]);
        setCalculationType(null);
        setRecordedIndices(new Set());
        setMainView('landing');
        setAnalysisMode(null);
        setGroupFertilizerSelections([]);
    };

    const handleSaveToHistory = () => {
        if (!results || !calculationType) return;
        const newReport: SavedReport = {
            id: Date.now().toString(),
            timestamp: new Date().toISOString(),
            formData: currentFormData,
            results: results!,
            calculationType: calculationType!,
            springFertilizer,
            nitrogenFertilizer,
            basicFertilizers,
            selectedAmendment,
            complexFertilizer,
            springFertilizerRate,
        };
        setReports(prev => [newReport, ...prev]);
        alert(t('saveToHistorySuccess', language));
    };

    const handleSaveDownload = () => {
        if (!calculationType) return;

        // Create the unified project structure
        const project: AgroProject = {
            version: '1.0',
            type: 'project',
            mode: analysisMode || 'single',
            analyses: analyses,
            activeAnalysisIndex: activeAnalysisIndex,
            calculationType: calculationType,
            selections: analysisMode === 'group' 
                ? groupFertilizerSelections 
                : [{
                    springFertilizer,
                    nitrogenFertilizer,
                    basicFertilizers,
                    selectedAmendment,
                    complexFertilizer,
                    springFertilizerRate,
                }]
        };

        const blob = new Blob([JSON.stringify(project, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        const fileName = currentFormData.fieldName ? `${currentFormData.fieldName}_` : '';
        const projectPrefix = analysisMode === 'group' ? 'agro_group_session' : `agro_project_${fileName}${currentFormData.culture}`;

        a.href = url;
        a.download = `${projectPrefix}.json`;
        a.click();
        URL.revokeObjectURL(url);
    };

    const handleEditReport = (report: SavedReport) => {
        setMainView('calculator');
        setAnalysisMode('single');
        setAnalyses([report.formData]);
        setActiveAnalysisIndex(0);
        setResults(report.results);
        setCalculationType(report.calculationType);
        setSpringFertilizer(report.springFertilizer);
        setNitrogenFertilizer(report.nitrogenFertilizer);
        setBasicFertilizers(report.basicFertilizers);
        setSelectedAmendment(report.selectedAmendment);
        setComplexFertilizer(report.complexFertilizer || createInitialComplexFertilizer());
        setSpringFertilizerRate(report.springFertilizerRate ?? null);
        setCurrentStep(4);
        setSelectedReport(null);
    };

    const handleLoadProject = (project: AgroProject) => {
        setMainView('calculator');
        setAnalysisMode(project.mode);
        setAnalyses(project.analyses);
        setActiveAnalysisIndex(project.activeAnalysisIndex);
        setCalculationType(project.calculationType);

        if (project.mode === 'single') {
            const sel = project.selections[0];
            setSpringFertilizer(sel.springFertilizer);
            setNitrogenFertilizer(sel.nitrogenFertilizer);
            setBasicFertilizers(sel.basicFertilizers);
            setSelectedAmendment(sel.selectedAmendment);
            setComplexFertilizer(sel.complexFertilizer);
            setSpringFertilizerRate(sel.springFertilizerRate);
            setResults(calculateNutrientNeeds(project.analyses[0]));
        } else {
            setGroupFertilizerSelections(project.selections);
            const allResults = project.analyses.map(f => calculateNutrientNeeds(f));
            setGroupResults(allResults);
            setRecordedIndices(new Set(project.analyses.map((_, i) => i)));
        }

        setCurrentStep(4);
        setSelectedReport(null);
    };

    const handleRecordCalculation = () => {
        setRecordedIndices(prev => {
            const next = new Set(prev);
            if (next.has(activeAnalysisIndex)) next.delete(activeAnalysisIndex);
            else next.add(activeAnalysisIndex);
            return next;
        });
    };

    const handleContinue = () => {
        setAnalyses(prev => [...prev, { ...INITIAL_FORM_DATA, culture: 'Томат', plannedYield: '100' }]);
        setActiveAnalysisIndex(analyses.length);
        setCurrentStep(1);
    };

    const handleOpenSaveModal = () => setIsSaveModalOpen(true);

    const handleConfirmSave = (selectedIndices: number[]) => {
        const reportsToSave = selectedIndices.map(index => {
            const formData = analyses[index];
            const result = groupResults[index];
            const selections = groupFertilizerSelections[index];
            if (!formData || !result || !selections || !calculationType) return null;
            return {
                formData,
                results: result,
                calculationType,
                cultureParams: CULTURE_PARAMS[formData.culture],
                springFertilizer: selections.springFertilizer,
                nitrogenFertilizer: selections.nitrogenFertilizer,
                basicFertilizers: selections.basicFertilizers,
                selectedAmendment: selections.selectedAmendment,
                complexFertilizer: selections.complexFertilizer,
                springFertilizerRate: selections.springFertilizerRate,
                lang: language
            };
        }).filter(Boolean);

        if (reportsToSave.length > 0) generateXlsxReport(reportsToSave as any, language);
        setIsSaveModalOpen(false);
    };

    return (
        <div className="container mx-auto p-4 md:p-8 font-sans bg-slate-50 min-h-screen">
            {isSaveModalOpen && (
                <SaveConfirmationModal
                    isOpen={isSaveModalOpen}
                    onClose={() => setIsSaveModalOpen(false)}
                    onConfirm={handleConfirmSave}
                    analyses={analyses}
                    recordedIndices={recordedIndices}
                    lang={language}
                />
            )}
            <input type="file" ref={fileInputRef} onChange={e => {
                const file = e.target.files?.[0];
                if (file) {
                    const reader = new FileReader();
                    reader.onloadend = () => {
                        const b64 = reader.result as string;
                        localStorage.setItem('custom-logo', b64);
                        setCustomLogoUrl(b64);
                    };
                    reader.readAsDataURL(file);
                }
            }} accept="image/*" className="hidden" />
            <input type="file" ref={reportInputRef} onChange={e => {
                const file = e.target.files?.[0];
                if (file) {
                    const reader = new FileReader();
                    reader.onload = e => {
                        try {
                            const data = JSON.parse(e.target?.result as string);
                            // Differentiate between a Project (restorable session) and a simple Report
                            if (data.type === 'project') {
                                handleLoadProject(data as AgroProject);
                            } else if (!Array.isArray(data) && data.formData && data.results) {
                                handleEditReport(data as SavedReport);
                            } else {
                                setReports(prev => [...(Array.isArray(data) ? data : [data]), ...prev]);
                                alert(t('reportLoadSuccessOne', language));
                            }
                        } catch (err) { alert(t('reportLoadError', language)); }
                    };
                    reader.readAsText(file);
                }
            }} className="hidden" />

            <header className="bg-gradient-to-r from-indigo-700 to-indigo-900 text-white p-4 md:p-6 rounded-xl shadow-2xl mb-10 flex justify-between items-center">
                <div className="flex items-center gap-4">
                     <div className="relative group cursor-pointer" onClick={() => fileInputRef.current?.click()}>
                        {customLogoUrl ? <img src={customLogoUrl} className="h-14 w-14 rounded-full object-cover" /> : <Logo className="h-14 w-14" />}
                    </div>
                    <div>
                        <h1 className="text-xl md:text-3xl font-bold">{t('headerTitle', language)}</h1>
                        <p className="text-indigo-200 hidden sm:block">Harvest Consulting</p>
                    </div>
                </div>
                <div className="flex items-center gap-4">
                     <button onClick={() => setMainView(mainView === 'reports' ? 'calculator' : 'reports')} className="bg-white/10 hover:bg-white/20 text-white font-semibold py-2 px-4 rounded-lg">
                        {mainView === 'reports' ? t('calculator', language) : t('reports', language)}
                    </button>
                </div>
            </header>

            {mainView === 'landing' && (
                <main className="bg-white p-12 rounded-xl shadow-lg text-center">
                    <h2 className="text-3xl font-bold text-slate-800">{t('landingTitle', language)}</h2>
                    <p className="mt-4 text-slate-600 max-w-2xl mx-auto">{t('landingDescription', language)}</p>
                    <div className="mt-10 flex flex-col sm:flex-row justify-center gap-6">
                        <button onClick={() => { setAnalysisMode('single'); setMainView('calculator'); }} className="bg-indigo-600 text-white font-bold py-4 px-8 rounded-lg">
                            {t('singleAnalysis', language)}
                        </button>
                        <button onClick={() => { setAnalysisMode('group'); setMainView('calculator'); }} className="bg-emerald-600 text-white font-bold py-4 px-8 rounded-lg">
                            {t('groupAnalysis', language)}
                        </button>
                    </div>
                </main>
            )}

            {mainView === 'calculator' && (
                <main className="bg-white p-6 rounded-xl shadow-lg">
                    {analysisMode === 'group' && (
                        <div className="mb-6 flex gap-2 overflow-x-auto pb-2 border-b">
                            {analyses.map((a, i) => (
                                <button key={i} onClick={() => setActiveAnalysisIndex(i)} className={`py-2 px-4 rounded-t-lg text-sm font-semibold ${activeAnalysisIndex === i ? 'bg-indigo-600 text-white' : 'text-slate-600 hover:bg-slate-200'}`}>
                                    {a.fieldName || t('analysisTab', language, { index: i + 1 })}
                                </button>
                            ))}
                            <button onClick={() => setAnalyses([...analyses, {...INITIAL_FORM_DATA}])} className="text-indigo-600 font-bold px-4">+</button>
                        </div>
                    )}
                    <Stepper currentStep={currentStep} steps={[t('step1', language), t('step2', language), t('step3', language), t('step4', language)]} />
                    <div className="mt-8">
                        {currentStep === 1 && <Step1SoilAnalysis onNext={handleNext} onBack={() => setMainView('landing')} data={currentFormData} onDataChange={updateCurrentAnalysis} lang={language} />}
                        {currentStep === 2 && <Step2CropYield onBack={handleBack} onCalculate={analysisMode === 'single' ? handleCalculate : handleCalculateAll} data={currentFormData} onDataChange={updateCurrentAnalysis} isGroupMode={analysisMode === 'group'} isCalculationDisabled={false} lang={language} />}
                        {currentStep === 3 && <Step3CalculationChoice onBack={handleBack} onSelect={handleSelectCalculation} lang={language} />}
                        {currentStep === 4 && (results || groupResults[activeAnalysisIndex]) && calculationType && (
                            <Step4Results 
                                onReset={handleReset} onBack={handleBack} results={(analysisMode === 'single' ? results : groupResults[activeAnalysisIndex])!}
                                type={calculationType!} formData={currentFormData} cultureParams={CULTURE_PARAMS[currentFormData.culture]}
                                onSaveToHistory={handleSaveToHistory} onSaveDownload={handleSaveDownload} 
                                springFertilizer={analysisMode === 'single' ? springFertilizer : (groupFertilizerSelections[activeAnalysisIndex]?.springFertilizer || createInitialSpringFertilizer())}
                                setSpringFertilizer={analysisMode === 'single' ? setSpringFertilizer : (val) => setGroupFertilizerSelections(prev => { const next = [...prev]; next[activeAnalysisIndex].springFertilizer = typeof val === 'function' ? (val as any)(next[activeAnalysisIndex].springFertilizer) : val; return next; })}
                                nitrogenFertilizer={analysisMode === 'single' ? nitrogenFertilizer : (groupFertilizerSelections[activeAnalysisIndex]?.nitrogenFertilizer || 'ammonium-nitrate')}
                                setNitrogenFertilizer={analysisMode === 'single' ? setNitrogenFertilizer : (val) => setGroupFertilizerSelections(prev => { const next = [...prev]; next[activeAnalysisIndex].nitrogenFertilizer = typeof val === 'function' ? (val as any)(next[activeAnalysisIndex].nitrogenFertilizer) : val; return next; })}
                                basicFertilizers={analysisMode === 'single' ? basicFertilizers : (groupFertilizerSelections[activeAnalysisIndex]?.basicFertilizers || {})}
                                setBasicFertilizers={analysisMode === 'single' ? setBasicFertilizers : (val) => setGroupFertilizerSelections(prev => { const next = [...prev]; next[activeAnalysisIndex].basicFertilizers = typeof val === 'function' ? (val as any)(next[activeAnalysisIndex].basicFertilizers) : val; return next; })}
                                selectedAmendment={analysisMode === 'single' ? selectedAmendment : (groupFertilizerSelections[activeAnalysisIndex]?.selectedAmendment || '')}
                                setSelectedAmendment={analysisMode === 'single' ? setSelectedAmendment : (val) => setGroupFertilizerSelections(prev => { const next = [...prev]; next[activeAnalysisIndex].selectedAmendment = typeof val === 'function' ? (val as any)(next[activeAnalysisIndex].selectedAmendment) : val; return next; })}
                                complexFertilizer={analysisMode === 'single' ? complexFertilizer : (groupFertilizerSelections[activeAnalysisIndex]?.complexFertilizer || createInitialComplexFertilizer())}
                                setComplexFertilizer={analysisMode === 'single' ? setComplexFertilizer : (val) => setGroupFertilizerSelections(prev => { const next = [...prev]; next[activeAnalysisIndex].complexFertilizer = typeof val === 'function' ? (val as any)(next[activeAnalysisIndex].complexFertilizer) : val; return next; })}
                                springFertilizerRate={analysisMode === 'single' ? springFertilizerRate : (groupFertilizerSelections[activeAnalysisIndex]?.springFertilizerRate || null)}
                                setSpringFertilizerRate={analysisMode === 'single' ? setSpringFertilizerRate : (val) => setGroupFertilizerSelections(prev => { const next = [...prev]; next[activeAnalysisIndex].springFertilizerRate = typeof val === 'function' ? (val as any)(next[activeAnalysisIndex].springFertilizerRate) : val; return next; })}
                                isGroupMode={analysisMode === 'group'} onSaveAllTxt={() => {}} lang={language}
                                onRecord={handleRecordCalculation} onOpenSaveModal={handleOpenSaveModal} onContinue={handleContinue} recordedIndices={recordedIndices} activeAnalysisIndex={activeAnalysisIndex}
                           />
                        )}
                    </div>
                </main>
            )}

            {mainView === 'reports' && (
                selectedReport ? <ReportDetail report={selectedReport} onBack={() => setSelectedReport(null)} onEdit={handleEditReport} lang={language} /> :
                <ReportsList reports={reports} onView={setSelectedReport} onDelete={id => setReports(reports.filter(r => r.id !== id))} onNewCalculation={handleReset} onLoadReport={() => reportInputRef.current?.click()} lang={language} />
            )}

            <footer className="text-center mt-12 text-slate-500 text-sm">
                <p>{t('footerText', language, { year: new Date().getFullYear() })}</p>
            </footer>
        </div>
    );
}

export default App;

import React, { useEffect, useState, useMemo } from 'react';
import { FERTIGATION_SCHEDULES } from './FertigationSchedules';
import { FERTIGATION_CULTURES } from '../constants';
import type { NutrientNeeds, CultureParams, SpringFertilizer, FormData } from '../types';
import { calculateFertigationPlan } from '../utils/fertigationCalculator';
import { FertigationChart } from './FertigationChart';
import { Tooltip } from './Tooltip';
import { InfoIcon } from './InfoIcon';
import { CompatibilityModal } from './CompatibilityModal';
import { Language, t } from '../i18n';

interface FertigationProgramProps {
    initialNeeds: NutrientNeeds[];
    culture: string;
    cultureParams: CultureParams;
    formData: Partial<FormData>;
    springFertilizer: SpringFertilizer;
    setSpringFertilizer: React.Dispatch<React.SetStateAction<SpringFertilizer>>;
    nitrogenFertilizer: string;
    setNitrogenFertilizer: React.Dispatch<React.SetStateAction<string>>;
    springFertilizerRate: number | null;
    setSpringFertilizerRate: (rate: number | null) => void;
    readOnly?: boolean;
    lang: Language;
    isGroupMode?: boolean;
}

const NutrientInput: React.FC<{ label: string; name: string; value: string; onChange: (e: React.ChangeEvent<HTMLInputElement>) => void; disabled?: boolean; }> = ({ label, name, value, onChange, disabled }) => (
    <div>
        <label htmlFor={name} className="block text-sm font-medium text-slate-700 text-center">{label}</label>
        <div className="mt-1 relative rounded-md shadow-sm">
            <input
                type="number"
                name={name}
                id={name}
                value={value}
                onChange={onChange}
                className="w-full pl-3 pr-8 py-2 border border-slate-300 rounded-md text-center focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 disabled:bg-slate-100"
                placeholder="0"
                min="0"
                step="0.1"
                disabled={disabled}
            />
            <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none">
                <span className="text-slate-500 sm:text-sm">%</span>
            </div>
        </div>
    </div>
);


export const FertigationProgram: React.FC<FertigationProgramProps> = ({ 
    initialNeeds, 
    culture,
    cultureParams,
    formData,
    springFertilizer,
    setSpringFertilizer,
    nitrogenFertilizer,
    setNitrogenFertilizer,
    springFertilizerRate,
    setSpringFertilizerRate,
    readOnly = false,
    lang,
    isGroupMode = false,
}) => {
    const [isCompatibilityModalOpen, setIsCompatibilityModalOpen] = useState(false);
    const [isRateManuallySet, setIsRateManuallySet] = useState(false);

    useEffect(() => {
        if (!readOnly && !isGroupMode) {
            setSpringFertilizer({ n: '', p: '', k: '', ca: '', mg: '', enabled: false, kCompensation: 50 });
            setNitrogenFertilizer('ammonium-nitrate');
            setSpringFertilizerRate(null);
            setIsRateManuallySet(false);
        }
    }, [initialNeeds, setSpringFertilizer, setNitrogenFertilizer, setSpringFertilizerRate, readOnly, isGroupMode]);

    const findCultureKey = (cultureName: string) => {
        return Object.keys(FERTIGATION_CULTURES).find(key => 
            FERTIGATION_CULTURES[key as keyof typeof FERTIGATION_CULTURES].startsWith(cultureName)
        );
    };

    const cultureKey = findCultureKey(culture);
    const area = parseFloat(formData.fieldArea || '1') || 1;

    const calculatedRate = useMemo(() => {
        const kPercentage = parseFloat(springFertilizer.k);
        const initialKNeed = initialNeeds.find(n => n.element === 'K2O')?.norm ?? 0;
        const compensation = springFertilizer.kCompensation ?? 50;
        if (springFertilizer.enabled && kPercentage && kPercentage > 0 && initialKNeed > 0) {
            const rate = (initialKNeed * (compensation / 100) / kPercentage) * 100;
            return Math.round(rate);
        }
        return null;
    }, [springFertilizer.enabled, springFertilizer.k, initialNeeds, springFertilizer.kCompensation]);

    useEffect(() => {
        if (!readOnly && !isRateManuallySet) {
            setSpringFertilizerRate(calculatedRate);
        }
    }, [calculatedRate, readOnly, isRateManuallySet, setSpringFertilizerRate]);


    const planData = useMemo(() => {
        if (!cultureKey) {
            return {
                weeklyPlan: [],
                totals: { nitrogen: 0, phosphorus: 0, potassium: 0, calcium: 0, magnesium: 0 },
            };
        }

        const rateToUse = springFertilizerRate ?? calculatedRate;

        const newPlanData = calculateFertigationPlan({
            initialNeeds, cultureKey, cultureParams, springFertilizer, nitrogenFertilizer,
            manualRate: rateToUse
        });

        return {
            weeklyPlan: newPlanData.weeklyPlan,
            totals: newPlanData.totals,
        }

    }, [initialNeeds, cultureKey, cultureParams, springFertilizer, nitrogenFertilizer, springFertilizerRate, calculatedRate]);

    const { weeklyPlan, totals } = planData;

    const handleToggleSpringFertilizer = (e: React.ChangeEvent<HTMLInputElement>) => {
        const isEnabled = e.target.checked;
        setSpringFertilizer(prev => {
             if (isEnabled) {
                return { ...prev, enabled: true, kCompensation: prev.kCompensation || 50 };
            }
            return { n: '', p: '', k: '', ca: '', mg: '', enabled: false, kCompensation: 50 };
        });
        setIsRateManuallySet(false);
    };

    const handleFertilizerChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, value } = e.target;
        if (name === 'kCompensation') {
            setSpringFertilizer(prev => ({ ...prev, kCompensation: parseFloat(value) || 0 }));
            setIsRateManuallySet(false);
        } else {
            setSpringFertilizer(prev => ({ ...prev, [name]: value }));
        }
    };

    const handleYaraMilaClick = () => {
        setSpringFertilizer(prev => ({
            ...prev,
            enabled: true,
            n: '11', p: '11', k: '21', ca: '0', mg: '2.6',
        }));
        setIsRateManuallySet(false);
    };

    const handleRosafertClick = () => {
        setSpringFertilizer(prev => ({
            ...prev,
            enabled: true,
            n: '12', p: '12', k: '17', ca: '4.3', mg: '2',
        }));
        setIsRateManuallySet(false);
    };

    const handleDiammophoskaClick = () => {
        setSpringFertilizer(prev => ({
            ...prev,
            enabled: true,
            n: '9', p: '25', k: '25', ca: '0', mg: '0',
        }));
        setIsRateManuallySet(false);
    };

    const handleRateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const value = e.target.value;
        setSpringFertilizerRate(value === '' ? null : parseFloat(value));
        setIsRateManuallySet(true);
    };

    const handleAutoCalculateRate = () => {
        setSpringFertilizerRate(calculatedRate);
        setIsRateManuallySet(false);
    };


    if (!cultureKey || !FERTIGATION_SCHEDULES[cultureKey]) {
        return (
            <div>
                <h3 className="text-xl font-semibold mb-4 text-slate-700 border-b pb-2">{t('fertigationProgramHeader', lang)}</h3>
                <div className="bg-yellow-100 border-l-4 border-yellow-500 text-yellow-700 p-4" role="alert">
                    <p className="font-bold">{t('noScheduleWarningTitle', lang)}</p>
                    <p>{t('noScheduleWarningText', lang, { culture: culture })}</p>
                </div>
            </div>
        );
    }

    if (initialNeeds.every(need => need.norm === 0)) {
         return (
            <div>
                <h3 className="text-xl font-semibold mb-4 text-slate-700 border-b pb-2">{t('fertigationProgramHeader', lang)}</h3>
                <p>{t('fertigationNotNeeded', lang)}</p>
            </div>
        );
    }

    const nitrogenFertilizerName = nitrogenFertilizer === 'ammonium-nitrate' ? t('ammoniumNitrate', lang) : t('urea', lang);
    const chartLabels = [nitrogenFertilizerName, 'Ортофосфорна к-та', 'Сульфат калію', 'Нітрат кальцію', 'Сульфат магнію'];
    if (lang === 'en') {
        chartLabels[1] = 'Orthophosphoric acid';
        chartLabels[2] = 'Potassium sulfate';
        chartLabels[3] = 'Calcium nitrate';
        chartLabels[4] = 'Magnesium sulfate';
    }

    const rateTooltipText = t('springFertilizerRateTooltip', lang, { percent: springFertilizer.kCompensation || 50 });

    return (
        <div>
            <h3 className="text-xl font-semibold mb-4 text-slate-700 border-b pb-2">{t('fertigationProgramHeader', lang)}</h3>

             <div className="mb-6 p-4 border border-indigo-200 rounded-lg bg-indigo-50">
                <div className="relative flex items-start">
                    <div className="flex h-6 items-center">
                        <input id="spring-fert-toggle" aria-describedby="spring-fert-description" name="spring-fert-toggle" type="checkbox" checked={springFertilizer.enabled} onChange={handleToggleSpringFertilizer} className="h-4 w-4 rounded border-slate-300 text-indigo-600 focus:ring-indigo-600" disabled={readOnly} />
                    </div>
                    <div className="ml-3 text-sm leading-6">
                        <label htmlFor="spring-fert-toggle" className="font-medium text-slate-900 cursor-pointer">
                            {t('addSpringFertilizer', lang)}
                        </label>
                        <p id="spring-fert-description" className="text-slate-500">
                            {t('addSpringFertilizerDesc', lang)}
                        </p>
                    </div>
                </div>
            </div>

            {springFertilizer.enabled && (
                <div className="mb-8 p-4 border rounded-lg bg-slate-50 space-y-4 shadow-inner">
                     <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-2">
                        <h4 className="text-lg font-semibold text-slate-800">{t('springFertilizerHeader', lang)}</h4>
                        {!readOnly && (
                            <div className="flex flex-wrap gap-2">
                                <button type="button" onClick={handleYaraMilaClick} className="bg-indigo-100 text-indigo-700 text-xs font-semibold px-4 py-1.5 rounded-full hover:bg-indigo-200 transition-colors flex-shrink-0" title="Заповнити поля даними YaraMila CROPCARE 11-11-21">
                                    {t('yaraMilaButton', lang)}
                                </button>
                                <button type="button" onClick={handleRosafertClick} className="bg-emerald-100 text-emerald-700 text-xs font-semibold px-4 py-1.5 rounded-full hover:bg-emerald-200 transition-colors flex-shrink-0" title="Заповнити поля даними ROSAFERT 12-12-17">
                                    {t('rosafertButton', lang)}
                                </button>
                                <button type="button" onClick={handleDiammophoskaClick} className="bg-amber-100 text-amber-700 text-xs font-semibold px-4 py-1.5 rounded-full hover:bg-amber-200 transition-colors flex-shrink-0" title="Заповнити поля даними Діамофоска 9-25-25">
                                    {t('diammophoskaButton', lang)}
                                </button>
                            </div>
                        )}
                     </div>

                     <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-4">
                         <NutrientInput label={t('nitrogenAnalysisLabel', lang)} name="n" value={springFertilizer.n} onChange={handleFertilizerChange} disabled={readOnly} />
                         <NutrientInput label={t('phosphorusLabel', lang)} name="p" value={springFertilizer.p} onChange={handleFertilizerChange} disabled={readOnly} />
                         <NutrientInput label={t('potassiumLabel', lang)} name="k" value={springFertilizer.k} onChange={handleFertilizerChange} disabled={readOnly} />
                         <NutrientInput label={t('calciumLabel', lang)} name="ca" value={springFertilizer.ca} onChange={handleFertilizerChange} disabled={readOnly} />
                         <NutrientInput label={t('magnesiumLabel', lang)} name="mg" value={springFertilizer.mg} onChange={handleFertilizerChange} disabled={readOnly} />
                         <div className="relative group">
                            <label htmlFor="kCompensation" className="block text-sm font-medium text-slate-700 text-center flex items-center justify-center gap-1">
                                {t('kCompensationLabel', lang)}
                                <Tooltip text={t('kCompensationTooltip', lang)}><InfoIcon className="h-4 w-4" /></Tooltip>
                            </label>
                            <div className="mt-1 relative rounded-md shadow-sm">
                                <input
                                    type="number"
                                    name="kCompensation"
                                    id="kCompensation"
                                    value={springFertilizer.kCompensation ?? 50}
                                    onChange={handleFertilizerChange}
                                    className="w-full pl-3 pr-8 py-2 border border-indigo-300 bg-indigo-50/50 rounded-md text-center font-semibold text-indigo-700 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 disabled:bg-slate-100"
                                    placeholder="50"
                                    min="0"
                                    max="100"
                                    step="1"
                                    disabled={readOnly}
                                />
                                <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none">
                                    <span className="text-indigo-500 sm:text-sm">%</span>
                                </div>
                            </div>
                        </div>
                     </div>
                     <div className="pt-2">
                         <div className="bg-indigo-100/60 p-3 rounded-lg">
                            <div className="flex flex-col sm:flex-row justify-between sm:items-center gap-2">
                                 <label htmlFor="manual-rate" className="font-medium text-slate-800 flex items-center gap-1.5">
                                     {t('applicationRate', lang)}
                                     <Tooltip text={rateTooltipText}><InfoIcon className="h-4 w-4" /></Tooltip>
                                 </label>
                                 <div className="flex items-center gap-2">
                                     {!readOnly && (
                                         <button 
                                             type="button" 
                                             onClick={handleAutoCalculateRate} 
                                             className="bg-indigo-200 text-indigo-800 text-xs font-semibold px-3 py-1.5 rounded-md hover:bg-indigo-300 transition"
                                             title={t('autoCalculateTooltip', lang)}
                                         >
                                             {t('autoCalculateButton', lang)}
                                         </button>
                                     )}
                                     <div className="relative">
                                         <input
                                            type="number"
                                            id="manual-rate"
                                            value={springFertilizerRate ?? ''}
                                            onChange={handleRateChange}
                                            disabled={readOnly}
                                            className="w-32 text-right font-bold text-lg text-indigo-700 bg-white/50 border border-indigo-200 rounded-md py-1.5 pl-3 pr-14 focus:outline-none focus:ring-2 focus:ring-indigo-400 disabled:bg-slate-100 disabled:text-slate-500"
                                            placeholder={calculatedRate?.toString() || '0'}
                                            min="0"
                                            step="1"
                                         />
                                         <span className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 pointer-events-none">kg/ha</span>
                                     </div>
                                 </div>
                            </div>
                             {(springFertilizerRate ?? 0) > 0 && <p className="text-sm text-slate-600 mt-2 text-right font-medium">{t('totalForArea', lang)} <span className="font-bold text-indigo-700">{(springFertilizerRate! * area).toFixed(1)} kg</span></p>}
                         </div>
                     </div>
                </div>
            )}

            <div className="mb-8 p-4 border rounded-lg bg-slate-50 space-y-4">
                <h4 className="text-lg font-semibold text-slate-800">{t('nitrogenFertilizerChoiceHeader', lang)}</h4>
                 <div>
                    <label htmlFor="nitrogen-fertilizer" className="block text-sm font-medium text-slate-700">{t('nitrogenFertilizerLabel', lang)}</label>
                    <select id="nitrogen-fertilizer" value={nitrogenFertilizer} onChange={(e) => setNitrogenFertilizer(e.target.value)} className="mt-1 block w-full md:w-1/3 pl-3 pr-10 py-2 text-base border-slate-300 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm rounded-md disabled:bg-slate-100" disabled={readOnly}>
                        <option value="ammonium-nitrate">{t('ammoniumNitrate', lang)}</option>
                        <option value="urea">{t('urea', lang)}</option>
                    </select>
                </div>
            </div>

            <div className="flex flex-col sm:flex-row justify-between items-center mb-4 gap-4">
                 <h4 className="text-lg font-semibold text-slate-800">{t('weeklyPlanHeader', lang)}</h4>
                 <button type="button" onClick={() => setIsCompatibilityModalOpen(true)} className="flex-shrink-0 flex items-center gap-2 bg-white text-indigo-700 border-2 border-indigo-200 font-semibold py-2 px-4 rounded-lg hover:bg-indigo-50 hover:border-indigo-300 transition-colors duration-300 focus:outline-none focus:ring-2 focus:ring-indigo-400 focus:ring-offset-2 text-sm">
                     <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}><path strokeLinecap="round" strokeLinejoin="round" d="M19.428 15.428a2 2 0 00-1.022-.547l-2.387-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z" /></svg>
                     <span>{t('compatibilityTableButton', lang)}</span>
                 </button>
            </div>


            {weeklyPlan && weeklyPlan.length > 0 ? (
                <FertigationChart data={weeklyPlan} labels={chartLabels} fieldArea={area} lang={lang} sowingDate={formData.sowingDate} />
            ) : (
                <div className="text-center py-8 bg-slate-50 rounded-lg">
                    <p className="text-slate-600">Немає даних для побудови графіка.</p>
                </div>
            )}

            <div className="mt-8">
                 <h4 className="text-lg font-semibold mb-4 text-slate-800">{t('totalForSeasonHeader', lang)}</h4>
                 <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-4">
                     {[
                         { label: chartLabels[0], value: totals.nitrogen, color: 'border-indigo-500' },
                         { label: chartLabels[1], value: totals.phosphorus, color: 'border-emerald-500' },
                         { label: chartLabels[2], value: totals.potassium, color: 'border-amber-500' },
                         { label: chartLabels[3], value: totals.calcium, color: 'border-sky-500' },
                         { label: chartLabels[4], value: totals.magnesium, color: 'border-rose-500' },
                     ].map(item => (
                        <div key={item.label} className={`bg-slate-50 p-4 rounded-lg shadow-sm border-t-4 ${item.color}`}>
                            <p className="text-sm text-slate-600 truncate" title={item.label}>{item.label}</p>
                            <p className="text-2xl font-bold text-slate-800 mt-1">{item.value.toFixed(1)} <span className="text-base font-medium text-slate-500">kg/ha</span></p>
                            <p className="text-sm font-semibold text-indigo-700">{t('totalLabel', lang)} {(item.value * area).toFixed(1)} kg</p>
                        </div>
                     ))}
                 </div>
            </div>
            <CompatibilityModal isOpen={isCompatibilityModalOpen} onClose={() => setIsCompatibilityModalOpen(false)} nitrogenFertilizerName={nitrogenFertilizerName} lang={lang} />
        </div>
    );
};
